namespace BackEndAluguel.Application.Auth;

/// <summary>
/// Contrato para hashing e verificação de senhas.
/// A implementação concreta fica na camada Infrastructure (PBKDF2-SHA256).
/// </summary>
public interface ISenhaServico
{
    /// <summary>
    /// Gera um hash seguro da senha em texto plano.
    /// </summary>
    /// <param name="senhaPlana">Senha em texto plano fornecida pelo usuário.</param>
    /// <returns>Hash da senha (base64, inclui salt).</returns>
    string HashearSenha(string senhaPlana);

    /// <summary>
    /// Verifica se a senha em texto plano corresponde ao hash armazenado.
    /// </summary>
    /// <param name="senhaPlana">Senha em texto plano a verificar.</param>
    /// <param name="hashArmazenado">Hash armazenado no banco de dados.</param>
    /// <returns>True se a senha for correta.</returns>
    bool VerificarSenha(string senhaPlana, string hashArmazenado);
}

namespace BackEndAluguel.Application.Configuracoes.DTOs;

/// <summary>
/// DTO de leitura da configuracao global do sistema.
/// </summary>
public record ConfiguracaoDto(
    /// <summary>Identificador unico da configuracao.</summary>
    Guid Id,
    /// <summary>Valor do kWh em reais (usado para calcular o custo de energia).</summary>
    decimal KwhValor,
    /// <summary>Valor fixo mensal da agua cobrado de todos os inquilinos.</summary>
    decimal ValorAgua,
    /// <summary>Data da ultima atualizacao da configuracao.</summary>
    DateTime? AtualizadoEm,
    /// <summary>
    /// WalletId do Host na plataforma Asaas.
    /// Preenchido apos o registro da subconta via endpoint de integracao Asaas.
    /// </summary>
    string? WalletIdAsaas = null
);

namespace BackEndAluguel.Application.Configuracoes.DTOs;

/// <summary>
/// DTO de leitura da configuracao global do sistema.
/// </summary>
public record ConfiguracaoDto(
    /// <summary>Identificador unico da configuracao.</summary>
    Guid Id,
    /// <summary>Valor do kWh em reais (usado para calcular o custo de energia).</summary>
    decimal KwhValor,
    /// <summary>Valor fixo mensal da agua cobrado de todos os inquilinos.</summary>
    decimal ValorAgua,
    /// <summary>Data da ultima atualizacao da configuracao.</summary>
    DateTime? AtualizadoEm,
    /// <summary>WalletId do Host na plataforma Asaas.</summary>
    string? WalletIdAsaas = null,
    /// <summary>Número de WhatsApp do locador no formato internacional (ex: 5511999999999).</summary>
    string? NumeroWhatsappLocador = null,
    /// <summary>Template da mensagem padrão WhatsApp. Placeholders: {inquilino}, {mesReferencia}, {valorTotal}, {dataVencimento}, {codigoPix}.</summary>
    string? MensagemPadraoWhatsapp = null,
    /// <summary>Chave PIX do locador (para geração de código nativo sem gateway).</summary>
    string? ChavePix = null,
    /// <summary>Nome do recebedor PIX (máx. 25 chars).</summary>
    string? NomeRecebedorPix = null,
    /// <summary>Cidade do recebedor PIX (máx. 15 chars).</summary>
    string? CidadeRecebedorPix = null
);

/// <summary>
/// DTO de resultado do link WhatsApp gerado para uma fatura.
/// </summary>
public record WhatsAppLinkDto(
    /// <summary>URL wa.me com o número e mensagem pré-preenchida. Abrir no frontend.</summary>
    string LinkWhatsApp,
    /// <summary>Mensagem formatada que será enviada.</summary>
    string Mensagem,
    /// <summary>Código PIX copia-e-cola gerado para inclusão na mensagem (nulo se ChavePix não configurada).</summary>
    string? CodigoPix,
    /// <summary>Número de telefone do inquilino (para referência).</summary>
    string TelefoneInquilino
);

using BackEndAluguel.Application.Comum.Excecoes;
using BackEndAluguel.Application.Configuracoes.Comandos;
using BackEndAluguel.Application.Configuracoes.Consultas;
using BackEndAluguel.Application.Configuracoes.DTOs;
using BackEndAluguel.Application.Pagamentos;
using BackEndAluguel.Application.Pagamentos.DTOs;
using BackEndAluguel.Domain.Entidades;
using BackEndAluguel.Domain.Interfaces;
using MediatR;

namespace BackEndAluguel.Application.Configuracoes.Manipuladores;

/// <summary>
/// Manipulador CQRS para a consulta <see cref="ObterConfiguracaoConsulta"/>.
/// Retorna a configuracao global unica do sistema.
/// </summary>
public class ObterConfiguracaoManipulador : IRequestHandler<ObterConfiguracaoConsulta, ConfiguracaoDto?>
{
    private readonly IConfiguracaoRepositorio _repositorio;

    /// <summary>Inicializa o manipulador com o repositorio de configuracoes.</summary>
    public ObterConfiguracaoManipulador(IConfiguracaoRepositorio repositorio)
    {
        _repositorio = repositorio;
    }

    /// <summary>Processa a consulta retornando a configuracao atual.</summary>
    public async Task<ConfiguracaoDto?> Handle(ObterConfiguracaoConsulta request, CancellationToken cancellationToken)
    {
        var config = await _repositorio.ObterConfiguracaoAsync(cancellationToken);
        return config is null ? null : ConverterParaDto(config);
    }

    /// <summary>Converte a entidade Configuracao para DTO de resposta.</summary>
    internal static ConfiguracaoDto ConverterParaDto(Configuracao c)
        => new(c.Id, c.KwhValor, c.ValorAgua, c.AtualizadoEm, c.WalletIdAsaas);
}

/// <summary>
/// Manipulador CQRS para o comando <see cref="AtualizarConfiguracaoComando"/>.
/// Atualiza os valores globais de kWh e agua do sistema.
/// </summary>
public class AtualizarConfiguracaoManipulador : IRequestHandler<AtualizarConfiguracaoComando, ConfiguracaoDto>
{
    private readonly IConfiguracaoRepositorio _repositorio;

    /// <summary>Inicializa o manipulador com o repositorio de configuracoes.</summary>
    public AtualizarConfiguracaoManipulador(IConfiguracaoRepositorio repositorio)
    {
        _repositorio = repositorio;
    }

    /// <summary>Processa a atualizacao da configuracao global do sistema (cria se nao existir — upsert).</summary>
    public async Task<ConfiguracaoDto> Handle(AtualizarConfiguracaoComando request, CancellationToken cancellationToken)
    {
        var config = await _repositorio.ObterConfiguracaoAsync(cancellationToken);

        if (config is null)
        {
            // Primeira configuracao: cria o registro singleton
            config = new Configuracao(request.KwhValor, request.ValorAgua);
            await _repositorio.AdicionarAsync(config, cancellationToken);
        }
        else
        {
            config.Atualizar(request.KwhValor, request.ValorAgua);
            _repositorio.Atualizar(config);
        }

        await _repositorio.SalvarAlteracoesAsync(cancellationToken);
        return ObterConfiguracaoManipulador.ConverterParaDto(config);
    }
}

/// <summary>
/// Manipulador CQRS para o comando <see cref="CriarSubcontaAsaasComando"/>.
/// Registra o locador (host) na plataforma Asaas, obtendo o WalletId para uso no split de pagamentos PIX.
/// O WalletId e armazenado na Configuracao global para uso automatico na geracao de cobranças.
/// </summary>
public class CriarSubcontaAsaasManipulador : IRequestHandler<CriarSubcontaAsaasComando, SubcontaResultadoDto>
{
    private readonly IConfiguracaoRepositorio _configuracaoRepositorio;
    private readonly IServicoGatewayPagamento _gatewayPagamento;

    /// <summary>Inicializa o manipulador com os servicos necessarios.</summary>
    public CriarSubcontaAsaasManipulador(
        IConfiguracaoRepositorio configuracaoRepositorio,
        IServicoGatewayPagamento gatewayPagamento)
    {
        _configuracaoRepositorio = configuracaoRepositorio;
        _gatewayPagamento = gatewayPagamento;
    }

    /// <summary>
    /// Registra a subconta no Asaas e persiste o WalletId retornado na configuracao global.
    /// </summary>
    public async Task<SubcontaResultadoDto> Handle(CriarSubcontaAsaasComando request, CancellationToken cancellationToken)
    {
        var dados = new CriarSubcontaDto(
            Nome: request.Nome,
            Email: request.Email,
            CpfCnpj: request.CpfCnpj,
            TipoPessoa: request.TipoPessoa,
            Telefone: request.Telefone,
            Site: request.Site);

        var resultado = await _gatewayPagamento.CriarSubcontaAsync(dados, cancellationToken);

        // Persiste o WalletId na configuracao global para uso futuro no split PIX
        var config = await _configuracaoRepositorio.ObterConfiguracaoAsync(cancellationToken)
            ?? throw new RegraDeNegocioExcecao("Configuracao global nao encontrada. Contate o suporte.");

        config.AtualizarWalletIdAsaas(resultado.WalletId);
        _configuracaoRepositorio.Atualizar(config);
        await _configuracaoRepositorio.SalvarAlteracoesAsync(cancellationToken);

        return resultado;
    }
}

using BackEndAluguel.Application.Comum;
using BackEndAluguel.Application.Comum.Excecoes;
using BackEndAluguel.Application.Configuracoes.Comandos;
using BackEndAluguel.Application.Configuracoes.Consultas;
using BackEndAluguel.Application.Configuracoes.DTOs;
using BackEndAluguel.Application.Pagamentos;
using BackEndAluguel.Application.Pagamentos.DTOs;
using BackEndAluguel.Domain.Entidades;
using BackEndAluguel.Domain.Interfaces;
using MediatR;

namespace BackEndAluguel.Application.Configuracoes.Manipuladores;

/// <summary>
/// Manipulador CQRS para a consulta <see cref="ObterConfiguracaoConsulta"/>.
/// Retorna a configuracao global unica do sistema.
/// </summary>
public class ObterConfiguracaoManipulador : IRequestHandler<ObterConfiguracaoConsulta, ConfiguracaoDto?>
{
    private readonly IConfiguracaoRepositorio _repositorio;

    /// <summary>Inicializa o manipulador com o repositorio de configuracoes.</summary>
    public ObterConfiguracaoManipulador(IConfiguracaoRepositorio repositorio)
    {
        _repositorio = repositorio;
    }

    /// <summary>Processa a consulta retornando a configuracao atual.</summary>
    public async Task<ConfiguracaoDto?> Handle(ObterConfiguracaoConsulta request, CancellationToken cancellationToken)
    {
        var config = await _repositorio.ObterConfiguracaoAsync(cancellationToken);
        return config is null ? null : ConverterParaDto(config);
    }

    /// <summary>Converte a entidade Configuracao para DTO de resposta.</summary>
    internal static ConfiguracaoDto ConverterParaDto(Configuracao c)
        => new(c.Id, c.KwhValor, c.ValorAgua, c.AtualizadoEm, c.WalletIdAsaas,
               c.NumeroWhatsappLocador, c.MensagemPadraoWhatsapp,
               c.ChavePix, c.NomeRecebedorPix, c.CidadeRecebedorPix);
}

/// <summary>
/// Manipulador CQRS para o comando <see cref="AtualizarConfiguracaoComando"/>.
/// Atualiza os valores globais de kWh e agua do sistema.
/// </summary>
public class AtualizarConfiguracaoManipulador : IRequestHandler<AtualizarConfiguracaoComando, ConfiguracaoDto>
{
    private readonly IConfiguracaoRepositorio _repositorio;
    private readonly ITenantContexto _tenantContexto;

    public AtualizarConfiguracaoManipulador(IConfiguracaoRepositorio repositorio, ITenantContexto tenantContexto)
    {
        _repositorio = repositorio;
        _tenantContexto = tenantContexto;
    }

    /// <summary>Processa a atualizacao da configuracao do host (cria se nao existir — upsert).</summary>
    public async Task<ConfiguracaoDto> Handle(AtualizarConfiguracaoComando request, CancellationToken cancellationToken)
    {
        var config = await _repositorio.ObterConfiguracaoAsync(cancellationToken);

        if (config is null)
        {
            // Primeira configuracao: cria o registro para este host
            var hostId = _tenantContexto.ObterHostId() ?? Guid.Empty;
            config = new Configuracao(request.KwhValor, request.ValorAgua, hostId);
            await _repositorio.AdicionarAsync(config, cancellationToken);
        }
        else
        {
            config.Atualizar(request.KwhValor, request.ValorAgua);
            _repositorio.Atualizar(config);
        }

        await _repositorio.SalvarAlteracoesAsync(cancellationToken);
        return ObterConfiguracaoManipulador.ConverterParaDto(config);
    }
}

/// <summary>
/// Manipulador CQRS para o comando <see cref="CriarSubcontaAsaasComando"/>.
/// Registra o locador (host) na plataforma Asaas, obtendo o WalletId para uso no split de pagamentos PIX.
/// O WalletId e armazenado na Configuracao global para uso automatico na geracao de cobranças.
/// </summary>
public class CriarSubcontaAsaasManipulador : IRequestHandler<CriarSubcontaAsaasComando, SubcontaResultadoDto>
{
    private readonly IConfiguracaoRepositorio _configuracaoRepositorio;
    private readonly IServicoGatewayPagamento _gatewayPagamento;

    /// <summary>Inicializa o manipulador com os servicos necessarios.</summary>
    public CriarSubcontaAsaasManipulador(
        IConfiguracaoRepositorio configuracaoRepositorio,
        IServicoGatewayPagamento gatewayPagamento)
    {
        _configuracaoRepositorio = configuracaoRepositorio;
        _gatewayPagamento = gatewayPagamento;
    }

    /// <summary>
    /// Registra a subconta no Asaas e persiste o WalletId retornado na configuracao global.
    /// </summary>
    public async Task<SubcontaResultadoDto> Handle(CriarSubcontaAsaasComando request, CancellationToken cancellationToken)
    {
        var dados = new CriarSubcontaDto(
            Nome: request.Nome,
            Email: request.Email,
            CpfCnpj: request.CpfCnpj,
            TipoPessoa: request.TipoPessoa,
            Telefone: request.Telefone,
            Site: request.Site);

        var resultado = await _gatewayPagamento.CriarSubcontaAsync(dados, cancellationToken);

        // Persiste o WalletId na configuracao global para uso futuro no split PIX
        var config = await _configuracaoRepositorio.ObterConfiguracaoAsync(cancellationToken)
            ?? throw new RegraDeNegocioExcecao("Configuracao global nao encontrada. Contate o suporte.");

        config.AtualizarWalletIdAsaas(resultado.WalletId);
        _configuracaoRepositorio.Atualizar(config);
        await _configuracaoRepositorio.SalvarAlteracoesAsync(cancellationToken);

        return resultado;
    }
}

/// <summary>
/// Manipulador CQRS para o comando <see cref="AtualizarWhatsappComando"/>.
/// Salva o número de WhatsApp do locador e o template de mensagem padrão.
/// </summary>
public class AtualizarWhatsappManipulador : IRequestHandler<AtualizarWhatsappComando, ConfiguracaoDto>
{
    private readonly IConfiguracaoRepositorio _repositorio;

    public AtualizarWhatsappManipulador(IConfiguracaoRepositorio repositorio) => _repositorio = repositorio;

    public async Task<ConfiguracaoDto> Handle(AtualizarWhatsappComando request, CancellationToken cancellationToken)
    {
        var config = await _repositorio.ObterConfiguracaoAsync(cancellationToken)
            ?? throw new RegraDeNegocioExcecao("Configuracao global nao encontrada. Use PUT /api/configuracoes para criar.");

        config.AtualizarWhatsapp(request.NumeroWhatsapp, request.MensagemPadrao);
        _repositorio.Atualizar(config);
        await _repositorio.SalvarAlteracoesAsync(cancellationToken);

        return ObterConfiguracaoManipulador.ConverterParaDto(config);
    }
}

/// <summary>
/// Manipulador CQRS para o comando <see cref="AtualizarPixNativoComando"/>.
/// Salva os dados de PIX nativo (chave, nome e cidade) para geração de código sem gateway.
/// </summary>
public class AtualizarPixNativoManipulador : IRequestHandler<AtualizarPixNativoComando, ConfiguracaoDto>
{
    private readonly IConfiguracaoRepositorio _repositorio;
    private readonly ITenantContexto _tenantContexto;

    public AtualizarPixNativoManipulador(IConfiguracaoRepositorio repositorio, ITenantContexto tenantContexto)
    {
        _repositorio = repositorio;
        _tenantContexto = tenantContexto;
    }

    public async Task<ConfiguracaoDto> Handle(AtualizarPixNativoComando request, CancellationToken cancellationToken)
    {
        var config = await _repositorio.ObterConfiguracaoAsync(cancellationToken);

        if (config is null)
        {
            var hostId = _tenantContexto.ObterHostId() ?? Guid.Empty;
            config = new Configuracao(0, 0, hostId);
            await _repositorio.AdicionarAsync(config, cancellationToken);
        }

        config.AtualizarPix(request.ChavePix, request.NomeRecebedor, request.CidadeRecebedor);
        _repositorio.Atualizar(config);
        await _repositorio.SalvarAlteracoesAsync(cancellationToken);

        return ObterConfiguracaoManipulador.ConverterParaDto(config);
    }
}

namespace BackEndAluguel.Application.Contratos.DTOs;

/// <summary>DTO de leitura dos metadados de um contrato assinado por inquilino.</summary>
public record ContratoInquilinoDto(
    /// <summary>Identificador unico do contrato.</summary>
    Guid Id,
    /// <summary>Identificador do inquilino vinculado.</summary>
    Guid InquilinoId,
    /// <summary>Nome original do arquivo enviado.</summary>
    string NomeOriginalArquivo,
    /// <summary>Tipo MIME do arquivo (application/pdf, image/jpeg, etc.).</summary>
    string TipoConteudo,
    /// <summary>Tamanho do arquivo em bytes.</summary>
    long TamanhoBytes,
    /// <summary>Tamanho formatado para exibicao (ex: "1.2 MB").</summary>
    string TamanhoFormatado,
    /// <summary>Descricao opcional do contrato.</summary>
    string? Descricao,
    /// <summary>Data de upload do arquivo.</summary>
    DateTime CriadoEm
);

namespace BackEndAluguel.Application.Contratos.DTOs;

/// <summary>DTO de leitura dos metadados de um contrato assinado por inquilino.</summary>
public record ContratoInquilinoDto(
    /// <summary>Identificador unico do contrato.</summary>
    Guid Id,
    /// <summary>Identificador do inquilino vinculado.</summary>
    Guid InquilinoId,
    /// <summary>Nome original do arquivo enviado.</summary>
    string NomeOriginalArquivo,
    /// <summary>Tipo MIME do arquivo (application/pdf, image/jpeg, etc.).</summary>
    string TipoConteudo,
    /// <summary>Tamanho do arquivo em bytes.</summary>
    long TamanhoBytes,
    /// <summary>Tamanho formatado para exibicao (ex: "1.2 MB").</summary>
    string TamanhoFormatado,
    /// <summary>Descricao opcional do contrato.</summary>
    string? Descricao,
    /// <summary>Data de upload do arquivo.</summary>
    DateTime CriadoEm,
    /// <summary>Caminho relativo do arquivo no servidor (usado no download).</summary>
    string CaminhoArquivo = ""
);

using BackEndAluguel.Application.Comum.Excecoes;
using BackEndAluguel.Application.Contratos.Comandos;
using BackEndAluguel.Application.Contratos.Consultas;
using BackEndAluguel.Application.Contratos.DTOs;
using BackEndAluguel.Domain.Entidades;
using BackEndAluguel.Domain.Interfaces;
using MediatR;

namespace BackEndAluguel.Application.Contratos.Manipuladores;

/// <summary>
/// Manipulador CQRS para registrar os metadados de um contrato enviado pelo usuario.
/// Valida a existencia do inquilino antes de persistir o registro.
/// </summary>
public class RegistrarContratoManipulador : IRequestHandler<RegistrarContratoComando, ContratoInquilinoDto>
{
    private readonly IContratoInquilinoRepositorio _contratoRepositorio;
    private readonly IInquilinoRepositorio _inquilinoRepositorio;

    /// <summary>Inicializa o manipulador com os repositorios necessarios.</summary>
    public RegistrarContratoManipulador(
        IContratoInquilinoRepositorio contratoRepositorio,
        IInquilinoRepositorio inquilinoRepositorio)
    {
        _contratoRepositorio = contratoRepositorio;
        _inquilinoRepositorio = inquilinoRepositorio;
    }

    /// <summary>Processa o registro dos metadados do contrato.</summary>
    public async Task<ContratoInquilinoDto> Handle(RegistrarContratoComando request, CancellationToken cancellationToken)
    {
        // Valida se o inquilino existe antes de registrar o contrato
        var inquilino = await _inquilinoRepositorio.ObterPorIdAsync(request.InquilinoId, cancellationToken)
            ?? throw new EntidadeNaoEncontradaExcecao(nameof(Inquilino), request.InquilinoId);

        var contrato = new ContratoInquilino(
            request.InquilinoId,
            request.NomeOriginalArquivo,
            request.CaminhoArquivo,
            request.TipoConteudo,
            request.TamanhoBytes,
            request.Descricao);

        await _contratoRepositorio.AdicionarAsync(contrato, cancellationToken);
        await _contratoRepositorio.SalvarAlteracoesAsync(cancellationToken);

        return ConverterParaDto(contrato);
    }

    /// <summary>Converte a entidade ContratoInquilino para o DTO de resposta.</summary>
    internal static ContratoInquilinoDto ConverterParaDto(ContratoInquilino c)
        => new(
            c.Id,
            c.InquilinoId,
            c.NomeOriginalArquivo,
            c.TipoConteudo,
            c.TamanhoBytes,
            FormatarTamanho(c.TamanhoBytes),
            c.Descricao,
            c.CriadoEm
        );

    /// <summary>Formata o tamanho do arquivo de forma legivel (KB, MB).</summary>
    private static string FormatarTamanho(long bytes)
    {
        if (bytes < 1024) return $"{bytes} B";
        if (bytes < 1024 * 1024) return $"{bytes / 1024.0:F1} KB";
        return $"{bytes / (1024.0 * 1024.0):F1} MB";
    }
}

/// <summary>Manipulador CQRS para atualizar a descricao de um contrato.</summary>
public class AtualizarDescricaoContratoManipulador : IRequestHandler<AtualizarDescricaoContratoComando, ContratoInquilinoDto>
{
    private readonly IContratoInquilinoRepositorio _repositorio;
    public AtualizarDescricaoContratoManipulador(IContratoInquilinoRepositorio repositorio) { _repositorio = repositorio; }

    public async Task<ContratoInquilinoDto> Handle(AtualizarDescricaoContratoComando request, CancellationToken cancellationToken)
    {
        var contrato = await _repositorio.ObterPorIdAsync(request.Id, cancellationToken)
            ?? throw new EntidadeNaoEncontradaExcecao(nameof(ContratoInquilino), request.Id);

        contrato.AtualizarDescricao(request.Descricao);
        _repositorio.Atualizar(contrato);
        await _repositorio.SalvarAlteracoesAsync(cancellationToken);
        return RegistrarContratoManipulador.ConverterParaDto(contrato);
    }
}

/// <summary>
/// Manipulador CQRS para remocao de um contrato.
/// Remove o registro do banco e delega a exclusao do arquivo fisico ao <see cref="IArquivoStorageServico"/>.
/// </summary>
public class RemoverContratoManipulador : IRequestHandler<RemoverContratoComando, bool>
{
    private readonly IContratoInquilinoRepositorio _repositorio;
    private readonly IArquivoStorageServico _arquivoStorage;

    public RemoverContratoManipulador(IContratoInquilinoRepositorio repositorio, IArquivoStorageServico arquivoStorage)
    {
        _repositorio = repositorio;
        _arquivoStorage = arquivoStorage;
    }

    public async Task<bool> Handle(RemoverContratoComando request, CancellationToken cancellationToken)
    {
        var contrato = await _repositorio.ObterPorIdAsync(request.Id, cancellationToken)
            ?? throw new EntidadeNaoEncontradaExcecao(nameof(ContratoInquilino), request.Id);

        // Delega a remocao do arquivo fisico para o servico de storage
        _arquivoStorage.DeletarArquivo(contrato.CaminhoArquivo);

        _repositorio.Remover(contrato);
        await _repositorio.SalvarAlteracoesAsync(cancellationToken);
        return true;
    }
}

/// <summary>Manipulador CQRS para obter contrato por ID.</summary>
public class ObterContratoPorIdManipulador : IRequestHandler<ObterContratoPorIdConsulta, ContratoInquilinoDto?>
{
    private readonly IContratoInquilinoRepositorio _repositorio;
    public ObterContratoPorIdManipulador(IContratoInquilinoRepositorio repositorio) { _repositorio = repositorio; }

    public async Task<ContratoInquilinoDto?> Handle(ObterContratoPorIdConsulta request, CancellationToken cancellationToken)
    {
        var contrato = await _repositorio.ObterPorIdAsync(request.Id, cancellationToken);
        return contrato is null ? null : RegistrarContratoManipulador.ConverterParaDto(contrato);
    }
}

/// <summary>Manipulador CQRS para listar contratos por inquilino.</summary>
public class ListarContratosPorInquilinoManipulador : IRequestHandler<ListarContratosPorInquilinoConsulta, IEnumerable<ContratoInquilinoDto>>
{
    private readonly IContratoInquilinoRepositorio _repositorio;
    public ListarContratosPorInquilinoManipulador(IContratoInquilinoRepositorio repositorio) { _repositorio = repositorio; }

    public async Task<IEnumerable<ContratoInquilinoDto>> Handle(ListarContratosPorInquilinoConsulta request, CancellationToken cancellationToken)
    {
        var contratos = await _repositorio.ObterPorInquilinoAsync(request.InquilinoId, cancellationToken);
        return contratos.Select(RegistrarContratoManipulador.ConverterParaDto);
    }
}

