/// <summary>
/// Entidade que representa um apartamento dentro do condomínio.
/// </summary>
public class Apartamento : EntidadeBase
{
    /// <summary>
    /// Número do apartamento (ex: 101, 202, 303).
    /// </summary>
    public string Numero { get; private set; } = string.Empty;

    /// <summary>
    /// Bloco/Torre ao qual o apartamento pertence. Opcional.
    /// </summary>
    public string Bloco { get; private set; } = string.Empty;

    /// <summary>
    /// Indica se o apartamento está atualmente ocupado por algum inquilino.
    /// </summary>
    public bool Ocupado { get; private set; }

    /// <summary>
    /// Identificador do host (locador) dono deste apartamento.
    /// Chave de isolamento multi-tenant — FK para a entidade Host.
    /// </summary>
    public Guid HostId { get; private set; }

    // =============================================================
    // RELACIONAMENTO: 1 Apartamento -> N Inquilinos
    // Um apartamento pode ser alugado por diversos inquilinos
    // ao longo do tempo (histórico), mas somente um pode estar
    // ativo (com contrato vigente) em determinado momento.
    // =============================================================

    /// <summary>
    /// Lista de inquilinos que já ocuparam ou ocupam o apartamento.
    /// Representa o relacionamento Um-para-Muitos (1:N) entre Apartamento e Inquilino.
    /// </summary>
    public ICollection<Inquilino> Inquilinos { get; private set; } = new List<Inquilino>();

    /// <summary>
    /// Gastos de manutenção do apartamento.
    /// </summary>
    public ICollection<GastoManutencao> GastosManutencao { get; private set; } = new List<GastoManutencao>();

    /// <summary>
    /// Construtor protegido requerido pelo Entity Framework Core.
    /// </summary>
    protected Apartamento() { }

    /// <summary>
    /// Cria uma nova instância de Apartamento com número e bloco definidos.
    /// </summary>
    /// <param name="numero">Número do apartamento.</param>
    /// <param name="bloco">Bloco ou torre do apartamento. Opcional.</param>
    /// <exception cref="ArgumentException">Lançado quando número estiver vazio.</exception>
    public Apartamento(string numero, string? bloco = null, Guid hostId = default)
    {
        ValidarNumero(numero);
        Numero = numero.Trim().ToUpper();
        Bloco = string.IsNullOrWhiteSpace(bloco) ? string.Empty : bloco.Trim().ToUpper();
        Ocupado = false;
        HostId = hostId;
    }

    /// <summary>
    /// Atualiza o número e/ou bloco do apartamento.
    /// </summary>
    /// <param name="numero">Novo número do apartamento.</param>
    /// <param name="bloco">Novo bloco do apartamento. Opcional.</param>
    public void Atualizar(string numero, string? bloco = null)
    {
        ValidarNumero(numero);
        Numero = numero.Trim().ToUpper();
        Bloco = string.IsNullOrWhiteSpace(bloco) ? string.Empty : bloco.Trim().ToUpper();
        MarcarComoAtualizado();
    }

    /// <summary>
    /// Marca o apartamento como ocupado quando um inquilino é vinculado.
    /// </summary>
    public void MarcarComoOcupado()
    {
        Ocupado = true;
        MarcarComoAtualizado();
    }

    /// <summary>
    /// Marca o apartamento como desocupado quando o inquilino encerra o contrato.
    /// </summary>
    public void MarcarComoDesocupado()
    {
        Ocupado = false;
        MarcarComoAtualizado();
    }

    /// <summary>
    /// Valida que o número do apartamento não está vazio.
    /// </summary>
    private static void ValidarNumero(string numero)
    {
        if (string.IsNullOrWhiteSpace(numero))
            throw new ArgumentException("O número do apartamento não pode ser vazio.", nameof(numero));
    }
}

namespace BackEndAluguel.Domain.Entidades;

/// <summary>
/// Configuracao global do sistema (singleton).
/// Armazena o valor do kWh e o valor fixo da agua usados na geracao de faturas.
/// </summary>
public class Configuracao : EntidadeBase
{
    /// <summary>Valor do kWh em reais (usado para calcular custo de energia).</summary>
    public decimal KwhValor { get; private set; }

    /// <summary>Valor fixo mensal da agua cobrado de todos os inquilinos.</summary>
    public decimal ValorAgua { get; private set; }

    /// <summary>
    /// WalletId do Host (locador) na plataforma Asaas.
    /// Obtido ao registrar a subconta via <c>CriarSubcontaAsync</c>.
    /// Usado no split de pagamento PIX para direcionar o valor ao locador.
    /// </summary>
    public string? WalletIdAsaas { get; private set; }

    protected Configuracao() { }

    public Configuracao(decimal kwhValor, decimal valorAgua)
    {
        ValidarValores(kwhValor, valorAgua);
        KwhValor = kwhValor;
        ValorAgua = valorAgua;
    }

    public void Atualizar(decimal kwhValor, decimal valorAgua)
    {
        ValidarValores(kwhValor, valorAgua);
        KwhValor = kwhValor;
        ValorAgua = valorAgua;
        MarcarComoAtualizado();
    }

    /// <summary>
    /// Armazena o WalletId retornado pelo Asaas apos o registro da subconta do host.
    /// </summary>
    /// <param name="walletId">WalletId fornecido pela API do Asaas.</param>
    public void AtualizarWalletIdAsaas(string walletId)
    {
        if (string.IsNullOrWhiteSpace(walletId))
            throw new ArgumentException("O WalletId do Asaas nao pode ser vazio.", nameof(walletId));
        WalletIdAsaas = walletId;
        MarcarComoAtualizado();
    }

    private static void ValidarValores(decimal kwhValor, decimal valorAgua)
    {
        if (kwhValor < 0)
            throw new ArgumentException("O valor do kWh nao pode ser negativo.", nameof(kwhValor));
        if (valorAgua < 0)
            throw new ArgumentException("O valor da agua nao pode ser negativo.", nameof(valorAgua));
    }
}

namespace BackEndAluguel.Domain.Entidades;

/// <summary>
/// Configuracao global do sistema (singleton).
/// Armazena o valor do kWh e o valor fixo da agua usados na geracao de faturas.
/// </summary>
public class Configuracao : EntidadeBase
{
    /// <summary>Valor do kWh em reais (usado para calcular custo de energia).</summary>
    public decimal KwhValor { get; private set; }

    /// <summary>Valor fixo mensal da agua cobrado de todos os inquilinos.</summary>
    public decimal ValorAgua { get; private set; }

    /// <summary>
    /// WalletId do Host (locador) na plataforma Asaas.
    /// Obtido ao registrar a subconta via <c>CriarSubcontaAsync</c>.
    /// Usado no split de pagamento PIX para direcionar o valor ao locador.
    /// </summary>
    public string? WalletIdAsaas { get; private set; }

    // ─── WhatsApp ──────────────────────────────────────────────────────────────

    /// <summary>
    /// Número de WhatsApp do locador no formato internacional sem o '+' (ex: 5511999999999).
    /// Usado para gerar o link wa.me para contato com o inquilino.
    /// </summary>
    public string? NumeroWhatsappLocador { get; private set; }

    /// <summary>
    /// Template da mensagem padrão enviada via WhatsApp ao inquilino quando a fatura é enviada.
    /// Suporta os placeholders: {inquilino}, {mesReferencia}, {valorTotal}, {dataVencimento}, {codigoPix}.
    /// </summary>
    public string? MensagemPadraoWhatsapp { get; private set; }

    // ─── PIX Nativo (sem gateway) ──────────────────────────────────────────────

    /// <summary>Chave PIX do locador (CPF, CNPJ, e-mail, telefone ou chave aleatória).</summary>
    public string? ChavePix { get; private set; }

    /// <summary>Nome do recebedor conforme cadastro PIX (máx. 25 caracteres).</summary>
    public string? NomeRecebedorPix { get; private set; }

    /// <summary>Cidade do recebedor conforme cadastro PIX (máx. 15 caracteres).</summary>
    public string? CidadeRecebedorPix { get; private set; }

    /// <summary>
    /// Identificador do host (locador) dono desta configuração.
    /// Chave de isolamento multi-tenant — FK para a entidade Host.
    /// </summary>
    public Guid HostId { get; private set; }

    protected Configuracao() { }

    public Configuracao(decimal kwhValor, decimal valorAgua, Guid hostId = default)
    {
        ValidarValores(kwhValor, valorAgua);
        KwhValor = kwhValor;
        ValorAgua = valorAgua;
        HostId = hostId;
    }

    public void Atualizar(decimal kwhValor, decimal valorAgua)
    {
        ValidarValores(kwhValor, valorAgua);
        KwhValor = kwhValor;
        ValorAgua = valorAgua;
        MarcarComoAtualizado();
    }

    /// <summary>
    /// Armazena o WalletId retornado pelo Asaas apos o registro da subconta do host.
    /// </summary>
    public void AtualizarWalletIdAsaas(string walletId)
    {
        if (string.IsNullOrWhiteSpace(walletId))
            throw new ArgumentException("O WalletId do Asaas nao pode ser vazio.", nameof(walletId));
        WalletIdAsaas = walletId;
        MarcarComoAtualizado();
    }

    /// <summary>
    /// Atualiza as configurações de integração com WhatsApp.
    /// </summary>
    /// <param name="numero">Número no formato internacional sem '+' (ex: 5511999999999).</param>
    /// <param name="mensagemPadrao">Template da mensagem. Use {inquilino}, {mesReferencia}, {valorTotal}, {dataVencimento}, {codigoPix}.</param>
    public void AtualizarWhatsapp(string numero, string mensagemPadrao)
    {
        if (string.IsNullOrWhiteSpace(numero))
            throw new ArgumentException("O numero de WhatsApp nao pode ser vazio.", nameof(numero));
        if (string.IsNullOrWhiteSpace(mensagemPadrao))
            throw new ArgumentException("A mensagem padrao nao pode ser vazia.", nameof(mensagemPadrao));
        NumeroWhatsappLocador = numero.Trim();
        MensagemPadraoWhatsapp = mensagemPadrao.Trim();
        MarcarComoAtualizado();
    }

    /// <summary>
    /// Atualiza as configurações de PIX nativo do locador.
    /// </summary>
    public void AtualizarPix(string chavePix, string nomeRecebedor, string cidadeRecebedor)
    {
        if (string.IsNullOrWhiteSpace(chavePix))
            throw new ArgumentException("A chave PIX nao pode ser vazia.", nameof(chavePix));
        if (string.IsNullOrWhiteSpace(nomeRecebedor))
            throw new ArgumentException("O nome do recebedor PIX nao pode ser vazio.", nameof(nomeRecebedor));
        if (string.IsNullOrWhiteSpace(cidadeRecebedor))
            throw new ArgumentException("A cidade do recebedor PIX nao pode ser vazia.", nameof(cidadeRecebedor));
        ChavePix = chavePix.Trim();
        NomeRecebedorPix = nomeRecebedor.Trim()[..Math.Min(nomeRecebedor.Trim().Length, 25)];
        CidadeRecebedorPix = cidadeRecebedor.Trim()[..Math.Min(cidadeRecebedor.Trim().Length, 15)];
        MarcarComoAtualizado();
    }

    private static void ValidarValores(decimal kwhValor, decimal valorAgua)
    {
        if (kwhValor < 0)
            throw new ArgumentException("O valor do kWh nao pode ser negativo.", nameof(kwhValor));
        if (valorAgua < 0)
            throw new ArgumentException("O valor da agua nao pode ser negativo.", nameof(valorAgua));
    }
}

using BackEndAluguel.Domain.Enumeradores;

namespace BackEndAluguel.Domain.Entidades;

/// <summary>
/// Representa um dependente vinculado a um inquilino.
/// </summary>
public class Dependente : EntidadeBase
{
    public string NomeCompleto { get; private set; } = string.Empty;
    public string Cpf { get; private set; } = string.Empty;
    public string Rg { get; private set; } = string.Empty;
    public string OrgaoEmissor { get; private set; } = string.Empty;
    public DateOnly DataNascimento { get; private set; }
    public string Telefone { get; private set; } = string.Empty;
    public EstadoCivil EstadoCivil { get; private set; }
    public Guid InquilinoId { get; private set; }
    public Inquilino? Inquilino { get; private set; }

    protected Dependente() { }

    public Dependente(
        string nomeCompleto,
        string cpf,
        string rg,
        string orgaoEmissor,
        DateOnly dataNascimento,
        string telefone,
        EstadoCivil estadoCivil,
        Guid inquilinoId)
    {
        ValidarNome(nomeCompleto);
        ValidarCpf(cpf);

        NomeCompleto = nomeCompleto.Trim();
        Cpf = LimparCpf(cpf);
        Rg = rg?.Trim() ?? string.Empty;
        OrgaoEmissor = orgaoEmissor?.Trim() ?? string.Empty;
        DataNascimento = dataNascimento;
        Telefone = telefone?.Trim() ?? string.Empty;
        EstadoCivil = estadoCivil;
        InquilinoId = inquilinoId;
    }

    public void Atualizar(
        string nomeCompleto,
        string rg,
        string orgaoEmissor,
        DateOnly dataNascimento,
        string telefone,
        EstadoCivil estadoCivil)
    {
        ValidarNome(nomeCompleto);
        NomeCompleto = nomeCompleto.Trim();
        Rg = rg?.Trim() ?? string.Empty;
        OrgaoEmissor = orgaoEmissor?.Trim() ?? string.Empty;
        DataNascimento = dataNascimento;
        Telefone = telefone?.Trim() ?? string.Empty;
        EstadoCivil = estadoCivil;
        MarcarComoAtualizado();
    }

    private static string LimparCpf(string cpf)
        => new(cpf.Where(char.IsDigit).ToArray());

    private static void ValidarNome(string nome)
    {
        if (string.IsNullOrWhiteSpace(nome))
            throw new ArgumentException("O nome completo do dependente nao pode ser vazio.", nameof(nome));
    }

    private static void ValidarCpf(string cpf)
    {
        var digitos = new string(cpf.Where(char.IsDigit).ToArray());
        if (digitos.Length != 11)
            throw new ArgumentException("O CPF do dependente deve conter 11 digitos numericos.", nameof(cpf));
    }
}

using BackEndAluguel.Domain.Enumeradores;

namespace BackEndAluguel.Domain.Entidades;

/// <summary>
/// Representa um dependente vinculado a um inquilino.
/// </summary>
public class Dependente : EntidadeBase
{
    public string NomeCompleto { get; private set; } = string.Empty;
    public string Cpf { get; private set; } = string.Empty;
    public string Rg { get; private set; } = string.Empty;
    public string OrgaoEmissor { get; private set; } = string.Empty;
    public DateOnly DataNascimento { get; private set; }
    public string Telefone { get; private set; } = string.Empty;
    public EstadoCivil EstadoCivil { get; private set; }
    public Guid InquilinoId { get; private set; }
    public Inquilino? Inquilino { get; private set; }

    protected Dependente() { }

    public Dependente(
        string nomeCompleto,
        string cpf,
        string rg,
        string orgaoEmissor,
        DateOnly dataNascimento,
        string telefone,
        EstadoCivil estadoCivil,
        Guid inquilinoId)
    {
        ValidarNome(nomeCompleto);
        ValidarCpf(cpf);
        ValidarRg(rg);
        ValidarOrgaoEmissor(orgaoEmissor);
        ValidarTelefone(telefone);

        NomeCompleto = nomeCompleto.Trim();
        Cpf = LimparCpf(cpf);
        Rg = rg.Trim();
        OrgaoEmissor = orgaoEmissor.Trim();
        DataNascimento = dataNascimento;
        Telefone = telefone.Trim();
        EstadoCivil = estadoCivil;
        InquilinoId = inquilinoId;
    }

    public void Atualizar(
        string nomeCompleto,
        string rg,
        string orgaoEmissor,
        DateOnly dataNascimento,
        string telefone,
        EstadoCivil estadoCivil)
    {
        ValidarNome(nomeCompleto);
        ValidarRg(rg);
        ValidarOrgaoEmissor(orgaoEmissor);
        ValidarTelefone(telefone);

        NomeCompleto = nomeCompleto.Trim();
        Rg = rg.Trim();
        OrgaoEmissor = orgaoEmissor.Trim();
        DataNascimento = dataNascimento;
        Telefone = telefone.Trim();
        EstadoCivil = estadoCivil;
        MarcarComoAtualizado();
    }

    private static string LimparCpf(string cpf)
        => new(cpf.Where(char.IsDigit).ToArray());

    private static void ValidarNome(string nome)
    {
        if (string.IsNullOrWhiteSpace(nome))
            throw new ArgumentException("O nome completo do dependente nao pode ser vazio.", nameof(nome));
    }

    private static void ValidarCpf(string cpf)
    {
        var digitos = new string(cpf.Where(char.IsDigit).ToArray());
        if (digitos.Length != 11)
            throw new ArgumentException("O CPF do dependente deve conter 11 digitos numericos.", nameof(cpf));
    }

    private static void ValidarRg(string rg)
    {
        if (string.IsNullOrWhiteSpace(rg))
            throw new ArgumentException("O RG do dependente e obrigatorio.", nameof(rg));
    }

    private static void ValidarOrgaoEmissor(string orgaoEmissor)
    {
        if (string.IsNullOrWhiteSpace(orgaoEmissor))
            throw new ArgumentException("O orgao emissor do RG do dependente e obrigatorio.", nameof(orgaoEmissor));
    }

    private static void ValidarTelefone(string telefone)
    {
        if (string.IsNullOrWhiteSpace(telefone))
            throw new ArgumentException("O telefone do dependente e obrigatorio.", nameof(telefone));
    }
}

using BackEndAluguel.Domain.Enumeradores;

namespace BackEndAluguel.Domain.Entidades;

/// <summary>
/// Entidade que representa uma fatura mensal de aluguel gerada para um inquilino.
/// Agrupa todos os valores cobrados em um determinado mês de referência,
/// bem como o controle de pagamento e as informações do PIX gerado.
///
/// Relacionamentos:
/// - N Faturas para 1 Inquilino (chave estrangeira InquilinoId).
///   Cada fatura pertence exclusivamente a um inquilino.
/// </summary>
public class Fatura : EntidadeBase
{
    /// <summary>
    /// Mês de referência da fatura no formato "MM/AAAA" (ex: "05/2025").
    /// Utilizado para identificar qual competência a fatura está cobrindo.
    /// </summary>
    public string MesReferencia { get; private set; } = string.Empty;

    /// <summary>
    /// Valor do aluguel mensal cobrado nesta fatura (em reais).
    /// Pode diferir do valor contratual em caso de reajuste ou negociação.
    /// </summary>
    public decimal ValorAluguel { get; private set; }

    /// <summary>
    /// Valor da conta de água referente ao mês de competência (em reais).
    /// </summary>
    public decimal ValorAgua { get; private set; }

    /// <summary>
    /// Valor da conta de luz (energia elétrica) referente ao mês de competência (em reais).
    /// </summary>
    public decimal ValorLuz { get; private set; }

    /// <summary>Leitura do kWh no mes anterior (inicio do periodo).</summary>
    public decimal? KwMesAnterior { get; private set; }

    /// <summary>Leitura do kWh no mes atual (fim do periodo).</summary>
    public decimal? KwAtual { get; private set; }

    /// <summary>Valor do kWh (tarifa) vigente no momento da geracao da fatura.</summary>
    public decimal? KwhValor { get; private set; }

    /// <summary>Consumo do periodo em kWh. Calculado: KwAtual - KwMesAnterior.</summary>
    public decimal? KwConsumidos =>
        KwAtual.HasValue && KwMesAnterior.HasValue
            ? KwAtual.Value - KwMesAnterior.Value
            : null;

    /// <summary>
    /// Data limite para que o pagamento seja realizado sem incidência de multa ou juros.
    /// </summary>
    public DateOnly DataLimitePagamento { get; private set; }

    /// <summary>
    /// Data em que o pagamento foi efetivamente realizado.
    /// Nulo quando a fatura ainda não foi paga.
    /// </summary>
    public DateOnly? DataPagamento { get; private set; }

    /// <summary>
    /// Código ou link do PIX gerado para facilitar o pagamento desta fatura.
    /// Pode conter a chave PIX copia-e-cola ou URL de pagamento.
    /// </summary>
    public string? CodigoPix { get; private set; }

    /// <summary>
    /// Identificador externo da cobrança no gateway de pagamento Asaas.
    /// Utilizado para correlacionar o webhook de confirmação de pagamento com a fatura.
    /// </summary>
    public string? CobrancaAsaasId { get; private set; }

    /// <summary>
    /// Status atual da fatura: Pendente, Atrasado ou Pago.
    /// Controla o ciclo de vida do pagamento mensal.
    /// </summary>
    public StatusFatura Status { get; private set; }

    // =============================================================
    // RELACIONAMENTO: N Faturas -> 1 Inquilino
    // Uma fatura sempre pertence a um único inquilino.
    // A chave estrangeira InquilinoId referencia a tabela Inquilinos.
    // =============================================================

    /// <summary>
    /// Identificador do inquilino a quem esta fatura pertence.
    /// Chave estrangeira para a entidade Inquilino.
    /// </summary>
    public Guid InquilinoId { get; private set; }

    /// <summary>
    /// Propriedade de navegação para o inquilino vinculado.
    /// Permite acessar os dados do inquilino diretamente através da fatura.
    /// </summary>
    public Inquilino? Inquilino { get; private set; }

    /// <summary>
    /// Construtor protegido requerido pelo Entity Framework Core.
    /// </summary>
    protected Fatura() { }

    /// <summary>
    /// Cria uma nova fatura mensal para um inquilino.
    /// O status inicial é sempre <see cref="StatusFatura.Pendente"/>.
    /// </summary>
    /// <param name="mesReferencia">Mês de referência no formato "MM/AAAA".</param>
    /// <param name="valorAluguel">Valor do aluguel a ser cobrado.</param>
    /// <param name="valorAgua">Valor da conta de água.</param>
    /// <param name="valorLuz">Valor da conta de luz.</param>
    /// <param name="dataLimitePagamento">Data limite para pagamento sem multa.</param>
    /// <param name="inquilinoId">Identificador do inquilino responsável pelo pagamento.</param>
    /// <param name="kwMesAnterior">Leitura do kWh no mês anterior (opcional).</param>
    /// <param name="kwAtual">Leitura do kWh no mês atual (opcional).</param>
    /// <param name="kwhValor">Valor do kWh vigente no momento da geração da fatura (opcional).</param>
    /// <param name="codigoPix">Código ou link PIX gerado para pagamento (opcional).</param>
    public Fatura(
        string mesReferencia,
        decimal valorAluguel,
        decimal valorAgua,
        decimal valorLuz,
        DateOnly dataLimitePagamento,
        Guid inquilinoId,
        decimal? kwMesAnterior = null,
        decimal? kwAtual = null,
        decimal? kwhValor = null,
        string? codigoPix = null)
    {
        ValidarMesReferencia(mesReferencia);
        if (valorAluguel <= 0)
            throw new ArgumentException("O valor do aluguel deve ser maior que zero.", nameof(valorAluguel));
        if (valorAgua < 0)
            throw new ArgumentException("O valor da agua nao pode ser negativo.", nameof(valorAgua));
        if (valorLuz < 0)
            throw new ArgumentException("O valor da luz nao pode ser negativo.", nameof(valorLuz));

        MesReferencia = mesReferencia.Trim();
        ValorAluguel = valorAluguel;
        ValorAgua = valorAgua;
        ValorLuz = valorLuz;
        DataLimitePagamento = dataLimitePagamento;
        InquilinoId = inquilinoId;
        KwMesAnterior = kwMesAnterior;
        KwAtual = kwAtual;
        KwhValor = kwhValor;
        CodigoPix = codigoPix;
        Status = StatusFatura.Pendente;
    }

    /// <summary>
    /// Calcula o valor total da fatura somando aluguel, água e luz.
    /// </summary>
    /// <returns>Soma de todos os valores cobrados na fatura.</returns>
    public decimal CalcularValorTotal() => ValorAluguel + ValorAgua + ValorLuz;

    /// <summary>
    /// Registra o pagamento da fatura, atualizando a data de pagamento e o status para Pago.
    /// </summary>
    /// <param name="dataPagamento">Data em que o pagamento foi realizado.</param>
    /// <exception cref="InvalidOperationException">Lançado se a fatura já estiver paga.</exception>
    public void RegistrarPagamento(DateOnly dataPagamento)
    {
        if (Status == StatusFatura.Pago)
            throw new InvalidOperationException("Esta fatura ja foi paga.");
        DataPagamento = dataPagamento;
        Status = StatusFatura.Pago;
        MarcarComoAtualizado();
    }

    /// <summary>
    /// Atualiza o status da fatura para Atrasado.
    /// Deve ser chamado quando a data limite de pagamento for ultrapassada sem pagamento.
    /// </summary>
    /// <exception cref="InvalidOperationException">Lançado se a fatura já estiver paga.</exception>
    public void MarcarComoAtrasado()
    {
        if (Status == StatusFatura.Pago)
            throw new InvalidOperationException("Nao e possivel marcar como atrasada uma fatura ja paga.");
        Status = StatusFatura.Atrasado;
        MarcarComoAtualizado();
    }

    /// <summary>
    /// Atualiza o código/link PIX associado a esta fatura.
    /// </summary>
    /// <param name="codigoPix">Novo código ou link do PIX.</param>
    public void AtualizarCodigoPix(string codigoPix)
    {
        CodigoPix = codigoPix;
        MarcarComoAtualizado();
    }

    /// <summary>
    /// Registra o identificador de cobrança retornado pelo gateway Asaas.
    /// Permite rastrear a fatura via webhook quando o pagamento for confirmado.
    /// </summary>
    /// <param name="cobrancaAsaasId">ID da cobrança no Asaas (ex: "pay_xxxxxxxxxxxx").</param>
    public void RegistrarCobrancaAsaas(string cobrancaAsaasId)
    {
        CobrancaAsaasId = cobrancaAsaasId;
        MarcarComoAtualizado();
    }

    /// <summary>
    /// Atualiza os valores de água e luz da fatura antes do pagamento.
    /// </summary>
    /// <param name="valorAgua">Novo valor da água.</param>
    /// <param name="valorLuz">Novo valor da luz.</param>
    /// <exception cref="InvalidOperationException">Lançado se a fatura já estiver paga.</exception>
    public void AtualizarValoresConsumo(decimal valorAgua, decimal valorLuz)
    {
        if (Status == StatusFatura.Pago)
            throw new InvalidOperationException("Nao e possivel alterar valores de uma fatura ja paga.");
        if (valorAgua < 0) throw new ArgumentException("O valor da agua nao pode ser negativo.", nameof(valorAgua));
        if (valorLuz < 0) throw new ArgumentException("O valor da luz nao pode ser negativo.", nameof(valorLuz));
        ValorAgua = valorAgua;
        ValorLuz = valorLuz;
        MarcarComoAtualizado();
    }

    /// <summary>
    /// Atualiza a leitura de kWh e recalcula o ValorLuz automaticamente se possivel.
    /// </summary>
    public void AtualizarLeituraKw(decimal kwAtual, decimal? kwhValorOverride = null)
    {
        if (Status == StatusFatura.Pago)
            throw new InvalidOperationException("Nao e possivel alterar valores de uma fatura ja paga.");

        KwAtual = kwAtual;
        if (kwhValorOverride.HasValue) KwhValor = kwhValorOverride.Value;

        // Auto-recalcular ValorLuz se todos os dados estao disponiveis
        if (KwAtual.HasValue && KwMesAnterior.HasValue && KwhValor.HasValue)
        {
            var consumido = KwAtual.Value - KwMesAnterior.Value;
            if (consumido >= 0)
                ValorLuz = consumido * KwhValor.Value;
        }

        MarcarComoAtualizado();
    }

    /// <summary>
    /// Verifica se a fatura está vencida (data limite ultrapassada e não paga).
    /// </summary>
    /// <returns>Verdadeiro se a fatura estiver vencida e não paga.</returns>
    public bool EstaVencida()
        => Status != StatusFatura.Pago && DataLimitePagamento < DateOnly.FromDateTime(DateTime.Today);

    /// <summary>
    /// Valida o formato do mês de referência (MM/AAAA).
    /// </summary>
    private static void ValidarMesReferencia(string mesReferencia)
    {
        if (string.IsNullOrWhiteSpace(mesReferencia))
            throw new ArgumentException("O mes de referencia nao pode ser vazio.", nameof(mesReferencia));
        if (!System.Text.RegularExpressions.Regex.IsMatch(mesReferencia.Trim(), @"^(0[1-9]|1[0-2])/\d{4}$"))
            throw new ArgumentException("O mes de referencia deve estar no formato MM/AAAA.", nameof(mesReferencia));
    }
}

using BackEndAluguel.Domain.Enumeradores;

namespace BackEndAluguel.Domain.Entidades;

/// <summary>
/// Entidade que representa uma fatura mensal de aluguel gerada para um inquilino.
/// Agrupa todos os valores cobrados em um determinado mês de referência,
/// bem como o controle de pagamento e as informações do PIX gerado.
///
/// Relacionamentos:
/// - N Faturas para 1 Inquilino (chave estrangeira InquilinoId).
///   Cada fatura pertence exclusivamente a um inquilino.
/// </summary>
public class Fatura : EntidadeBase
{
    /// <summary>
    /// Mês de referência da fatura no formato "MM/AAAA" (ex: "05/2025").
    /// Utilizado para identificar qual competência a fatura está cobrindo.
    /// </summary>
    public string MesReferencia { get; private set; } = string.Empty;

    /// <summary>
    /// Valor do aluguel mensal cobrado nesta fatura (em reais).
    /// Pode diferir do valor contratual em caso de reajuste ou negociação.
    /// </summary>
    public decimal ValorAluguel { get; private set; }

    /// <summary>
    /// Valor da conta de água referente ao mês de competência (em reais).
    /// </summary>
    public decimal ValorAgua { get; private set; }

    /// <summary>
    /// Valor da conta de luz (energia elétrica) referente ao mês de competência (em reais).
    /// </summary>
    public decimal ValorLuz { get; private set; }

    /// <summary>
    /// Valor mensal cobrado pela vaga de garagem nesta fatura (0 se não possui garagem).
    /// </summary>
    public decimal ValorGaragem { get; private set; }

    /// <summary>Leitura do kWh no mes anterior (inicio do periodo).</summary>
    public decimal? KwMesAnterior { get; private set; }

    /// <summary>Leitura do kWh no mes atual (fim do periodo).</summary>
    public decimal? KwAtual { get; private set; }

    /// <summary>Valor do kWh (tarifa) vigente no momento da geracao da fatura.</summary>
    public decimal? KwhValor { get; private set; }

    /// <summary>Consumo do periodo em kWh. Calculado: KwAtual - KwMesAnterior.</summary>
    public decimal? KwConsumidos =>
        KwAtual.HasValue && KwMesAnterior.HasValue
            ? KwAtual.Value - KwMesAnterior.Value
            : null;

    /// <summary>
    /// Data limite para que o pagamento seja realizado sem incidência de multa ou juros.
    /// </summary>
    public DateOnly DataLimitePagamento { get; private set; }

    /// <summary>
    /// Data em que o pagamento foi efetivamente realizado.
    /// Nulo quando a fatura ainda não foi paga.
    /// </summary>
    public DateOnly? DataPagamento { get; private set; }

    /// <summary>
    /// Código ou link do PIX gerado para facilitar o pagamento desta fatura.
    /// Pode conter a chave PIX copia-e-cola ou URL de pagamento.
    /// </summary>
    public string? CodigoPix { get; private set; }

    /// <summary>
    /// Identificador externo da cobrança no gateway de pagamento Asaas.
    /// Utilizado para correlacionar o webhook de confirmação de pagamento com a fatura.
    /// </summary>
    public string? CobrancaAsaasId { get; private set; }

    /// <summary>
    /// Status atual da fatura: Pendente, Atrasado ou Pago.
    /// Controla o ciclo de vida do pagamento mensal.
    /// </summary>
    public StatusFatura Status { get; private set; }

    // =============================================================
    // RELACIONAMENTO: N Faturas -> 1 Inquilino
    // Uma fatura sempre pertence a um único inquilino.
    // A chave estrangeira InquilinoId referencia a tabela Inquilinos.
    // =============================================================

    /// <summary>
    /// Identificador do inquilino a quem esta fatura pertence.
    /// Chave estrangeira para a entidade Inquilino.
    /// </summary>
    public Guid InquilinoId { get; private set; }

    /// <summary>
    /// Propriedade de navegação para o inquilino vinculado.
    /// Permite acessar os dados do inquilino diretamente através da fatura.
    /// </summary>
    public Inquilino? Inquilino { get; private set; }

    /// <summary>
    /// Identificador do host (locador) dono desta fatura.
    /// Chave de isolamento multi-tenant — FK para a entidade Host.
    /// </summary>
    public Guid HostId { get; private set; }

    /// <summary>
    /// Construtor protegido requerido pelo Entity Framework Core.
    /// </summary>
    protected Fatura() { }

    /// <summary>
    /// Cria uma nova fatura mensal para um inquilino.
    /// O status inicial é sempre <see cref="StatusFatura.Pendente"/>.
    /// </summary>
    /// <param name="mesReferencia">Mês de referência no formato "MM/AAAA".</param>
    /// <param name="valorAluguel">Valor do aluguel a ser cobrado.</param>
    /// <param name="valorAgua">Valor da conta de água.</param>
    /// <param name="valorLuz">Valor da conta de luz.</param>
    /// <param name="dataLimitePagamento">Data limite para pagamento sem multa.</param>
    /// <param name="inquilinoId">Identificador do inquilino responsável pelo pagamento.</param>
    /// <param name="kwMesAnterior">Leitura do kWh no mês anterior (opcional).</param>
    /// <param name="kwAtual">Leitura do kWh no mês atual (opcional).</param>
    /// <param name="kwhValor">Valor do kWh vigente no momento da geração da fatura (opcional).</param>
    /// <param name="codigoPix">Código ou link PIX gerado para pagamento (opcional).</param>
    /// <param name="valorGaragem">Valor da garagem neste mês (opcional, padrão 0).</param>
    public Fatura(
        string mesReferencia,
        decimal valorAluguel,
        decimal valorAgua,
        decimal valorLuz,
        DateOnly dataLimitePagamento,
        Guid inquilinoId,
        decimal? kwMesAnterior = null,
        decimal? kwAtual = null,
        decimal? kwhValor = null,
        string? codigoPix = null,
        decimal valorGaragem = 0m,
        Guid hostId = default)
    {
        ValidarMesReferencia(mesReferencia);
        if (valorAluguel <= 0)
            throw new ArgumentException("O valor do aluguel deve ser maior que zero.", nameof(valorAluguel));
        if (valorAgua < 0)
            throw new ArgumentException("O valor da agua nao pode ser negativo.", nameof(valorAgua));
        if (valorLuz < 0)
            throw new ArgumentException("O valor da luz nao pode ser negativo.", nameof(valorLuz));
        if (valorGaragem < 0)
            throw new ArgumentException("O valor da garagem nao pode ser negativo.", nameof(valorGaragem));

        MesReferencia = mesReferencia.Trim();
        ValorAluguel = valorAluguel;
        ValorAgua = valorAgua;
        ValorLuz = valorLuz;
        ValorGaragem = valorGaragem;
        DataLimitePagamento = dataLimitePagamento;
        InquilinoId = inquilinoId;
        KwMesAnterior = kwMesAnterior;
        KwAtual = kwAtual;
        KwhValor = kwhValor;
        CodigoPix = codigoPix;
        Status = StatusFatura.Pendente;
        HostId = hostId;
    }

    /// <summary>
    /// Calcula o valor total da fatura somando aluguel, água, luz e garagem.
    /// </summary>
    /// <returns>Soma de todos os valores cobrados na fatura.</returns>
    public decimal CalcularValorTotal() => ValorAluguel + ValorAgua + ValorLuz + ValorGaragem;

    /// <summary>
    /// Registra o pagamento da fatura, atualizando a data de pagamento e o status para Pago.
    /// </summary>
    /// <param name="dataPagamento">Data em que o pagamento foi realizado.</param>
    /// <exception cref="InvalidOperationException">Lançado se a fatura já estiver paga.</exception>
    public void RegistrarPagamento(DateOnly dataPagamento)
    {
        if (Status == StatusFatura.Pago)
            throw new InvalidOperationException("Esta fatura ja foi paga.");
        DataPagamento = dataPagamento;
        Status = StatusFatura.Pago;
        MarcarComoAtualizado();
    }

    /// <summary>
    /// Atualiza o status da fatura para Atrasado.
    /// Deve ser chamado quando a data limite de pagamento for ultrapassada sem pagamento.
    /// </summary>
    /// <exception cref="InvalidOperationException">Lançado se a fatura já estiver paga.</exception>
    public void MarcarComoAtrasado()
    {
        if (Status == StatusFatura.Pago)
            throw new InvalidOperationException("Nao e possivel marcar como atrasada uma fatura ja paga.");
        Status = StatusFatura.Atrasado;
        MarcarComoAtualizado();
    }

    /// <summary>
    /// Atualiza o código/link PIX associado a esta fatura.
    /// </summary>
    /// <param name="codigoPix">Novo código ou link do PIX.</param>
    public void AtualizarCodigoPix(string codigoPix)
    {
        CodigoPix = codigoPix;
        MarcarComoAtualizado();
    }

    /// <summary>
    /// Registra o identificador de cobrança retornado pelo gateway Asaas.
    /// Permite rastrear a fatura via webhook quando o pagamento for confirmado.
    /// </summary>
    /// <param name="cobrancaAsaasId">ID da cobrança no Asaas (ex: "pay_xxxxxxxxxxxx").</param>
    public void RegistrarCobrancaAsaas(string cobrancaAsaasId)
    {
        CobrancaAsaasId = cobrancaAsaasId;
        MarcarComoAtualizado();
    }

    /// <summary>
    /// Atualiza os valores de água e luz da fatura antes do pagamento.
    /// </summary>
    /// <param name="valorAgua">Novo valor da água.</param>
    /// <param name="valorLuz">Novo valor da luz.</param>
    /// <exception cref="InvalidOperationException">Lançado se a fatura já estiver paga.</exception>
    public void AtualizarValoresConsumo(decimal valorAgua, decimal valorLuz)
    {
        if (Status == StatusFatura.Pago)
            throw new InvalidOperationException("Nao e possivel alterar valores de uma fatura ja paga.");
        if (valorAgua < 0) throw new ArgumentException("O valor da agua nao pode ser negativo.", nameof(valorAgua));
        if (valorLuz < 0) throw new ArgumentException("O valor da luz nao pode ser negativo.", nameof(valorLuz));
        ValorAgua = valorAgua;
        ValorLuz = valorLuz;
        MarcarComoAtualizado();
    }

    /// <summary>
    /// Atualiza a leitura de kWh e recalcula o ValorLuz automaticamente se possivel.
    /// </summary>
    public void AtualizarLeituraKw(decimal kwAtual, decimal? kwhValorOverride = null)
    {
        if (Status == StatusFatura.Pago)
            throw new InvalidOperationException("Nao e possivel alterar valores de uma fatura ja paga.");

        KwAtual = kwAtual;
        if (kwhValorOverride.HasValue) KwhValor = kwhValorOverride.Value;

        // Auto-recalcular ValorLuz se todos os dados estao disponiveis
        if (KwAtual.HasValue && KwMesAnterior.HasValue && KwhValor.HasValue)
        {
            var consumido = KwAtual.Value - KwMesAnterior.Value;
            if (consumido >= 0)
                ValorLuz = consumido * KwhValor.Value;
        }

        MarcarComoAtualizado();
    }

    /// <summary>
    /// Verifica se a fatura está vencida (data limite ultrapassada e não paga).
    /// </summary>
    /// <returns>Verdadeiro se a fatura estiver vencida e não paga.</returns>
    public bool EstaVencida()
        => Status != StatusFatura.Pago && DataLimitePagamento < DateOnly.FromDateTime(DateTime.Today);

    /// <summary>
    /// Valida o formato do mês de referência (MM/AAAA).
    /// </summary>
    private static void ValidarMesReferencia(string mesReferencia)
    {
        if (string.IsNullOrWhiteSpace(mesReferencia))
            throw new ArgumentException("O mes de referencia nao pode ser vazio.", nameof(mesReferencia));
        if (!System.Text.RegularExpressions.Regex.IsMatch(mesReferencia.Trim(), @"^(0[1-9]|1[0-2])/\d{4}$"))
            throw new ArgumentException("O mes de referencia deve estar no formato MM/AAAA.", nameof(mesReferencia));
    }
}

namespace BackEndAluguel.Domain.Entidades;

/// <summary>
/// Representa um administrador (locador/host) da plataforma GestAluguel.
/// Cada host é um usuário com acesso total ao painel de gerenciamento.
/// A conta deve ser confirmada por e-mail antes de ser utilizada.
/// </summary>
public class Host : EntidadeBase
{
    // ─── Propriedades ──────────────────────────────────────────────────────

    /// <summary>Nome completo do host.</summary>
    public string NomeCompleto { get; private set; } = string.Empty;

    /// <summary>CPF do host (somente dígitos, 11 caracteres).</summary>
    public string Cpf { get; private set; } = string.Empty;

    /// <summary>Data de nascimento do host.</summary>
    public DateOnly DataNascimento { get; private set; }

    /// <summary>Endereço de e-mail do host. Utilizado como login.</summary>
    public string Email { get; private set; } = string.Empty;

    /// <summary>Hash da senha do host gerado via PBKDF2-SHA256.</summary>
    public string SenhaHash { get; private set; } = string.Empty;

    /// <summary>Indica se o e-mail foi confirmado. A conta só pode ser usada após confirmação.</summary>
    public bool EmailConfirmado { get; private set; }

    /// <summary>Token único para confirmação de e-mail. Nulo após a confirmação.</summary>
    public string? TokenConfirmacao { get; private set; }

    /// <summary>Data de expiração do token de confirmação de e-mail.</summary>
    public DateTime? TokenExpiracaoConfirmacao { get; private set; }

    // ─── Construtor ────────────────────────────────────────────────────────

    /// <summary>
    /// Construtor protegido exigido pelo Entity Framework Core.
    /// Use o construtor público para criar instâncias desta entidade.
    /// </summary>
    protected Host() { }

    /// <summary>
    /// Cria um novo host com os dados fornecidos.
    /// A conta começa como não confirmada e recebe um token de confirmação de e-mail.
    /// </summary>
    /// <param name="nomeCompleto">Nome completo do host.</param>
    /// <param name="cpf">CPF (com ou sem formatação — será limpo automaticamente).</param>
    /// <param name="dataNascimento">Data de nascimento do host.</param>
    /// <param name="email">E-mail do host. Será armazenado em minúsculas.</param>
    /// <param name="senhaHash">Senha já criptografada via PBKDF2.</param>
    public Host(string nomeCompleto, string cpf, DateOnly dataNascimento, string email, string senhaHash)
    {
        ValidarNome(nomeCompleto);
        ValidarCpf(cpf);
        ValidarEmail(email);
        ValidarSenhaHash(senhaHash);

        NomeCompleto = nomeCompleto.Trim();
        Cpf = new string(cpf.Where(char.IsDigit).ToArray());
        DataNascimento = dataNascimento;
        Email = email.Trim().ToLowerInvariant();
        SenhaHash = senhaHash;
        EmailConfirmado = false;
        GerarTokenConfirmacao();
    }

    // ─── Métodos de domínio ────────────────────────────────────────────────

    /// <summary>
    /// Confirma o e-mail do host, limpando o token de confirmação.
    /// </summary>
    public void ConfirmarEmail()
    {
        EmailConfirmado = true;
        TokenConfirmacao = null;
        TokenExpiracaoConfirmacao = null;
        MarcarComoAtualizado();
    }

    /// <summary>
    /// Gera um novo token de confirmação de e-mail com expiração de 48 horas.
    /// Útil para reenvio de e-mail de confirmação.
    /// </summary>
    public void GerarTokenConfirmacao()
    {
        TokenConfirmacao = Guid.NewGuid().ToString("N") + Guid.NewGuid().ToString("N");
        TokenExpiracaoConfirmacao = DateTime.UtcNow.AddHours(48);
        MarcarComoAtualizado();
    }

    /// <summary>
    /// Verifica se o token de confirmação informado é válido e não expirou.
    /// </summary>
    public bool TokenConfirmacaoValido(string token)
        => TokenConfirmacao == token
           && TokenExpiracaoConfirmacao.HasValue
           && TokenExpiracaoConfirmacao.Value > DateTime.UtcNow;

    /// <summary>
    /// Atualiza os dados pessoais do host.
    /// </summary>
    public void Atualizar(string nomeCompleto, DateOnly dataNascimento)
    {
        ValidarNome(nomeCompleto);
        NomeCompleto = nomeCompleto.Trim();
        DataNascimento = dataNascimento;
        MarcarComoAtualizado();
    }

    /// <summary>
    /// Atualiza o hash da senha do host.
    /// </summary>
    public void AtualizarSenha(string novaSenhaHash)
    {
        ValidarSenhaHash(novaSenhaHash);
        SenhaHash = novaSenhaHash;
        MarcarComoAtualizado();
    }

    // ─── Validações privadas ───────────────────────────────────────────────

    private static void ValidarNome(string nome)
    {
        if (string.IsNullOrWhiteSpace(nome))
            throw new ArgumentException("O nome completo do host é obrigatório.", nameof(nome));
    }

    private static void ValidarCpf(string cpf)
    {
        var digitos = new string(cpf.Where(char.IsDigit).ToArray());
        if (digitos.Length != 11)
            throw new ArgumentException("O CPF deve conter exatamente 11 dígitos.", nameof(cpf));
    }

    private static void ValidarEmail(string email)
    {
        if (string.IsNullOrWhiteSpace(email) || !email.Contains('@'))
            throw new ArgumentException("O e-mail informado é inválido.", nameof(email));
    }

    private static void ValidarSenhaHash(string senhaHash)
    {
        if (string.IsNullOrWhiteSpace(senhaHash))
            throw new ArgumentException("O hash da senha não pode ser vazio.", nameof(senhaHash));
    }
}

using BackEndAluguel.Domain.Enumeradores;

namespace BackEndAluguel.Domain.Entidades;

/// <summary>
/// Entidade que representa um inquilino (locatário) de um apartamento.
/// O inquilino é também um morador e, portanto, compartilha os mesmos campos
/// pessoais obrigatórios que os dependentes (RG, órgão emissor, telefone, estado civil).
///
/// Relacionamentos:
/// - N Inquilinos para 1 Apartamento (chave estrangeira ApartamentoId).
/// - 1 Inquilino para N Faturas: cada inquilino pode ter múltiplas faturas mensais geradas.
/// </summary>
public class Inquilino : EntidadeBase
{
    /// <summary>Nome completo do inquilino.</summary>
    public string NomeCompleto { get; private set; } = string.Empty;

    /// <summary>CPF do inquilino, armazenado somente com dígitos (11 caracteres).</summary>
    public string Cpf { get; private set; } = string.Empty;

    /// <summary>RG do inquilino.</summary>
    public string Rg { get; private set; } = string.Empty;

    /// <summary>Órgão emissor do RG (ex: SSP-SP).</summary>
    public string OrgaoEmissor { get; private set; } = string.Empty;

    /// <summary>
    /// Data de nascimento do inquilino.
    /// Utilizada como segundo fator de autenticação no login do inquilino.
    /// </summary>
    public DateOnly DataNascimento { get; private set; }

    /// <summary>Telefone de contato do inquilino.</summary>
    public string Telefone { get; private set; } = string.Empty;

    /// <summary>Estado civil do inquilino.</summary>
    public EstadoCivil EstadoCivil { get; private set; }

    /// <summary>
    /// Quantidade total de moradores que residirão no apartamento,
    /// incluindo o próprio inquilino.
    /// </summary>
    public int QuantidadeMoradores { get; private set; }

    /// <summary>
    /// Data em que o inquilino iniciou a ocupação do apartamento.
    /// </summary>
    public DateOnly DataEntrada { get; private set; }

    /// <summary>
    /// Data de vencimento do contrato de locação.
    /// </summary>
    public DateOnly DataVencimentoContrato { get; private set; }

    /// <summary>
    /// Valor fixo mensal do aluguel definido em contrato (em reais).
    /// </summary>
    public decimal ValorAluguel { get; private set; }

    /// <summary>
    /// Valor mensal cobrado pela vaga de garagem (0 se nao possui garagem).
    /// </summary>
    public decimal Garagem { get; private set; }

    /// <summary>
    /// Configuração dos alertas de vencimento de contrato em dias (ex: 30, 60, 90).
    /// Permite notificar o inquilino/administrador com antecedência sobre o fim do contrato.
    /// Armazenado como uma lista de inteiros representando os dias antes do vencimento.
    /// </summary>
    public List<int> DiasAlertaVencimento { get; private set; } = new();

    // =============================================================
    // RELACIONAMENTO: N Inquilinos -> 1 Apartamento
    // Vários inquilinos (histórico) podem estar vinculados a
    // um único apartamento. A chave estrangeira ApartamentoId
    // referencia a tabela Apartamentos.
    // =============================================================

    /// <summary>
    /// Identificador do apartamento ao qual este inquilino está vinculado.
    /// Chave estrangeira para a entidade Apartamento.
    /// </summary>
