using BackEndAluguel.Domain.Entidades;

namespace BackEndAluguel.Domain.Interfaces;

/// <summary>
/// Contrato do repositório de hosts (administradores/locadores).
/// </summary>
public interface IHostRepositorio : IRepositorio<Host>
{
    /// <summary>Busca um host pelo e-mail (case-insensitive).</summary>
    Task<Host?> ObterPorEmailAsync(string email, CancellationToken cancellationToken = default);

    /// <summary>Busca um host pelo CPF (somente dígitos).</summary>
    Task<Host?> ObterPorCpfAsync(string cpf, CancellationToken cancellationToken = default);

    /// <summary>Busca um host pelo token de confirmação de e-mail.</summary>
    Task<Host?> ObterPorTokenConfirmacaoAsync(string token, CancellationToken cancellationToken = default);

    /// <summary>Verifica se já existe um host com o e-mail informado.</summary>
    Task<bool> ExisteEmailAsync(string email, CancellationToken cancellationToken = default);

    /// <summary>Verifica se já existe um host com o CPF informado.</summary>
    Task<bool> ExisteCpfAsync(string cpf, CancellationToken cancellationToken = default);
}

using BackEndAluguel.Domain.Entidades;

namespace BackEndAluguel.Domain.Interfaces;

/// <summary>
/// Contrato específico de repositório para a entidade <see cref="Inquilino"/>.
/// Estende o repositório genérico com operações específicas para inquilinos.
/// </summary>
public interface IInquilinoRepositorio : IRepositorio<Inquilino>
{
    /// <summary>
    /// Verifica se já existe um inquilino cadastrado com o CPF informado.
    /// Utilizado para evitar duplicatas no cadastro.
    /// </summary>
    /// <param name="cpf">CPF do inquilino (somente dígitos).</param>
    /// <param name="cancellationToken">Token para cancelamento assíncrono.</param>
    /// <returns>Verdadeiro se já existir um inquilino com este CPF.</returns>
    Task<bool> ExistePorCpfAsync(string cpf, CancellationToken cancellationToken = default);

    /// <summary>
    /// Busca um inquilino pelo CPF.
    /// </summary>
    /// <param name="cpf">CPF do inquilino (somente dígitos).</param>
    /// <param name="cancellationToken">Token para cancelamento assíncrono.</param>
    /// <returns>O inquilino encontrado ou nulo.</returns>
    Task<Inquilino?> ObterPorCpfAsync(string cpf, CancellationToken cancellationToken = default);

    /// <summary>
    /// Retorna todos os inquilinos vinculados a um apartamento específico.
    /// Inclui histórico de inquilinos (não apenas o atual).
    /// </summary>
    /// <param name="apartamentoId">Identificador do apartamento.</param>
    /// <param name="cancellationToken">Token para cancelamento assíncrono.</param>
    /// <returns>Lista de inquilinos do apartamento.</returns>
    Task<IEnumerable<Inquilino>> ObterPorApartamentoAsync(Guid apartamentoId, CancellationToken cancellationToken = default);

    /// <summary>
    /// Retorna os inquilinos cujos contratos vencem dentro do número de dias informado.
    /// Utilizado para geração de alertas de vencimento de contrato.
    /// </summary>
    /// <param name="diasAntecedencia">Quantidade de dias para antecipação do alerta.</param>
    /// <param name="cancellationToken">Token para cancelamento assíncrono.</param>
    /// <returns>Lista de inquilinos com contrato próximo do vencimento.</returns>
    Task<IEnumerable<Inquilino>> ObterComContratoProximoVencimentoAsync(int diasAntecedencia, CancellationToken cancellationToken = default);

    /// <summary>
    /// Busca o inquilino ativo de um apartamento com as faturas incluídas.
    /// </summary>
    /// <param name="apartamentoId">Identificador do apartamento.</param>
    /// <param name="cancellationToken">Token para cancelamento assíncrono.</param>
    /// <returns>O inquilino com as faturas carregadas ou nulo.</returns>
    Task<Inquilino?> ObterComFaturasPorApartamentoAsync(Guid apartamentoId, CancellationToken cancellationToken = default);
}

using BackEndAluguel.Domain.Entidades;

namespace BackEndAluguel.Domain.Interfaces;

/// <summary>
/// Contrato específico de repositório para a entidade <see cref="Inquilino"/>.
/// Estende o repositório genérico com operações específicas para inquilinos.
/// </summary>
public interface IInquilinoRepositorio : IRepositorio<Inquilino>
{
    /// <summary>
    /// Verifica se já existe um inquilino cadastrado com o CPF informado.
    /// Utilizado para evitar duplicatas no cadastro.
    /// </summary>
    /// <param name="cpf">CPF do inquilino (somente dígitos).</param>
    /// <param name="cancellationToken">Token para cancelamento assíncrono.</param>
    /// <returns>Verdadeiro se já existir um inquilino com este CPF.</returns>
    Task<bool> ExistePorCpfAsync(string cpf, CancellationToken cancellationToken = default);

    /// <summary>
    /// Busca um inquilino pelo CPF.
    /// </summary>
    /// <param name="cpf">CPF do inquilino (somente dígitos).</param>
    /// <param name="cancellationToken">Token para cancelamento assíncrono.</param>
    /// <returns>O inquilino encontrado ou nulo.</returns>
    Task<Inquilino?> ObterPorCpfAsync(string cpf, CancellationToken cancellationToken = default);

    /// <summary>
    /// Retorna todos os inquilinos vinculados a um apartamento específico.
    /// Inclui histórico de inquilinos (não apenas o atual).
    /// </summary>
    /// <param name="apartamentoId">Identificador do apartamento.</param>
    /// <param name="cancellationToken">Token para cancelamento assíncrono.</param>
    /// <returns>Lista de inquilinos do apartamento.</returns>
    Task<IEnumerable<Inquilino>> ObterPorApartamentoAsync(Guid apartamentoId, CancellationToken cancellationToken = default);

    /// <summary>
    /// Retorna os inquilinos cujos contratos vencem dentro do número de dias informado.
    /// Utilizado para geração de alertas de vencimento de contrato.
    /// </summary>
    /// <param name="diasAntecedencia">Quantidade de dias para antecipação do alerta.</param>
    /// <param name="cancellationToken">Token para cancelamento assíncrono.</param>
    /// <returns>Lista de inquilinos com contrato próximo do vencimento.</returns>
    Task<IEnumerable<Inquilino>> ObterComContratoProximoVencimentoAsync(int diasAntecedencia, CancellationToken cancellationToken = default);

    /// <summary>
    /// Busca o inquilino ativo de um apartamento com as faturas incluídas.
    /// </summary>
    /// <param name="apartamentoId">Identificador do apartamento.</param>
    /// <param name="cancellationToken">Token para cancelamento assíncrono.</param>
    /// <returns>O inquilino com as faturas carregadas ou nulo.</returns>
    Task<Inquilino?> ObterComFaturasPorApartamentoAsync(Guid apartamentoId, CancellationToken cancellationToken = default);

    /// <summary>
    /// Autentica um inquilino pelo CPF e data de nascimento.
    /// </summary>
    /// <param name="cpf">CPF do inquilino (somente dígitos).</param>
    /// <param name="dataNascimento">Data de nascimento do inquilino.</param>
    /// <param name="cancellationToken">Token para cancelamento assíncrono.</param>
    /// <returns>O inquilino correspondente ou nulo se não encontrado.</returns>
    Task<Inquilino?> ObterPorCpfEDataNascimentoAsync(string cpf, DateOnly dataNascimento, CancellationToken cancellationToken = default);
}

namespace BackEndAluguel.Domain.Interfaces;

/// <summary>
/// Contrato para geração de payload PIX no padrão EMV (copia-e-cola) do Banco Central do Brasil.
/// Não requer nenhuma API externa — o código é gerado localmente.
/// </summary>
public interface IPixPayloadGerador
{
    /// <summary>
    /// Gera o código PIX copia-e-cola conforme especificação EMV do BACEN.
    /// </summary>
    /// <param name="chavePix">Chave PIX do recebedor (CPF, CNPJ, e-mail, telefone ou chave aleatória).</param>
    /// <param name="nomeRecebedor">Nome do recebedor (máx. 25 caracteres).</param>
    /// <param name="cidadeRecebedor">Cidade do recebedor (máx. 15 caracteres).</param>
    /// <param name="valor">Valor da transação. Se nulo, gera PIX sem valor fixo.</param>
    /// <param name="txId">Identificador da transação (máx. 25 chars, apenas alfanumérico). Se nulo, usa "***".</param>
    /// <returns>String do payload PIX pronto para copiar e pagar.</returns>
    string Gerar(string chavePix, string nomeRecebedor, string cidadeRecebedor,
                 decimal? valor = null, string? txId = null);
}

using BackEndAluguel.Domain.Entidades;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace BackEndAluguel.Infrastructure.Configuracoes;

/// <summary>
/// Configuração do mapeamento da entidade <see cref="Apartamento"/> para o banco de dados.
/// Segue o padrão IEntityTypeConfiguration do EF Core para manter o contexto limpo (SRP).
/// </summary>
public class ApartamentoConfiguracao : IEntityTypeConfiguration<Apartamento>
{
    /// <summary>
    /// Configura a tabela, colunas, restrições e relacionamentos da entidade Apartamento.
    /// </summary>
    /// <param name="builder">Construtor de configuração da entidade.</param>
    public void Configure(EntityTypeBuilder<Apartamento> builder)
    {
        // Nome da tabela no banco de dados
        builder.ToTable("Apartamentos");

        // Chave primária
        builder.HasKey(a => a.Id);

        builder.Property(a => a.Id)
            .HasColumnName("Id")
            .IsRequired();

        // Número do apartamento — máximo 20 caracteres, obrigatório
        builder.Property(a => a.Numero)
            .HasColumnName("Numero")
            .HasMaxLength(20)
            .IsRequired();

        // Bloco/Torre — máximo 10 caracteres, opcional
        builder.Property(a => a.Bloco)
            .HasColumnName("Bloco")
            .HasMaxLength(10)
            .IsRequired(false)
            .HasDefaultValue(string.Empty);

        // Status de ocupação
        builder.Property(a => a.Ocupado)
            .HasColumnName("Ocupado")
            .IsRequired()
            .HasDefaultValue(false);

        // Auditorias de data
        builder.Property(a => a.CriadoEm)
            .HasColumnName("CriadoEm")
            .IsRequired();

        builder.Property(a => a.AtualizadoEm)
            .HasColumnName("AtualizadoEm")
            .IsRequired(false);

        // Índice único: não pode existir dois apartamentos com mesmo número e bloco
        builder.HasIndex(a => new { a.Numero, a.Bloco })
            .IsUnique()
            .HasDatabaseName("IX_Apartamentos_Numero_Bloco");

        // =============================================================
        // RELACIONAMENTO: 1 Apartamento -> N Inquilinos
        // Um apartamento pode ter vários inquilinos ao longo do tempo.
        // A deleção do apartamento não deve remover os inquilinos
        // (Restrict) para preservar o histórico.
        // =============================================================
        builder.HasMany(a => a.Inquilinos)
            .WithOne(i => i.Apartamento)
            .HasForeignKey(i => i.ApartamentoId)
            .OnDelete(DeleteBehavior.Restrict);
    }
}

using BackEndAluguel.Domain.Entidades;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace BackEndAluguel.Infrastructure.Configuracoes;

/// <summary>
/// Configuração do mapeamento da entidade <see cref="Apartamento"/> para o banco de dados.
/// Segue o padrão IEntityTypeConfiguration do EF Core para manter o contexto limpo (SRP).
/// </summary>
public class ApartamentoConfiguracao : IEntityTypeConfiguration<Apartamento>
{
    /// <summary>
    /// Configura a tabela, colunas, restrições e relacionamentos da entidade Apartamento.
    /// </summary>
    /// <param name="builder">Construtor de configuração da entidade.</param>
    public void Configure(EntityTypeBuilder<Apartamento> builder)
    {
        // Nome da tabela no banco de dados
        builder.ToTable("Apartamentos");

        // Chave primária
        builder.HasKey(a => a.Id);

        builder.Property(a => a.Id)
            .HasColumnName("Id")
            .IsRequired();

        // Número do apartamento — máximo 20 caracteres, obrigatório
        builder.Property(a => a.Numero)
            .HasColumnName("Numero")
            .HasMaxLength(20)
            .IsRequired();

        // Bloco/Torre — máximo 10 caracteres, opcional
        builder.Property(a => a.Bloco)
            .HasColumnName("Bloco")
            .HasMaxLength(10)
            .IsRequired(false)
            .HasDefaultValue(string.Empty);

        // Status de ocupação
        builder.Property(a => a.Ocupado)
            .HasColumnName("Ocupado")
            .IsRequired()
            .HasDefaultValue(false);

        // HostId — chave de isolamento multi-tenant
        builder.Property(a => a.HostId)
            .HasColumnName("HostId")
            .IsRequired();

        // FK para a tabela Hosts
        builder.HasOne<BackEndAluguel.Domain.Entidades.Host>()
            .WithMany()
            .HasForeignKey(a => a.HostId)
            .OnDelete(DeleteBehavior.Cascade);

        // Auditorias de data
        builder.Property(a => a.CriadoEm)
            .HasColumnName("CriadoEm")
            .IsRequired();

        builder.Property(a => a.AtualizadoEm)
            .HasColumnName("AtualizadoEm")
            .IsRequired(false);

        // Índice único: não pode existir dois apartamentos com mesmo número, bloco E host
        builder.HasIndex(a => new { a.HostId, a.Numero, a.Bloco })
            .IsUnique()
            .HasDatabaseName("IX_Apartamentos_HostId_Numero_Bloco");

        // =============================================================
        // RELACIONAMENTO: 1 Apartamento -> N Inquilinos
        // Um apartamento pode ter vários inquilinos ao longo do tempo.
        // A deleção do apartamento não deve remover os inquilinos
        // (Restrict) para preservar o histórico.
        // =============================================================
        builder.HasMany(a => a.Inquilinos)
            .WithOne(i => i.Apartamento)
            .HasForeignKey(i => i.ApartamentoId)
            .OnDelete(DeleteBehavior.Restrict);
    }
}

using BackEndAluguel.Domain.Entidades;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace BackEndAluguel.Infrastructure.Configuracoes;

public class ConfiguracaoConfiguracao : IEntityTypeConfiguration<Configuracao>
{
    // ID fixo para o registro singleton
    public static readonly Guid ConfiguracaoId = new("00000000-0000-0000-0000-000000000001");

    public void Configure(EntityTypeBuilder<Configuracao> builder)
    {
        builder.ToTable("Configuracoes");
        builder.HasKey(c => c.Id);

        builder.Property(c => c.KwhValor).HasPrecision(18, 4).IsRequired();
        builder.Property(c => c.ValorAgua).HasPrecision(18, 2).IsRequired();
        builder.Property(c => c.WalletIdAsaas).HasMaxLength(100).IsRequired(false);
        builder.Property(c => c.CriadoEm).IsRequired();
        builder.Property(c => c.AtualizadoEm).IsRequired(false);
