using BackEndAluguel.Infrastructure.Servicos;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;

namespace BackEndAluguel.Infrastructure;

/// <summary>
/// Classe de extensão para registro dos serviços da camada Infrastructure no contêiner de DI.
/// Centraliza o registro do DbContext, repositórios e serviços externos seguindo o princípio SRP.
/// </summary>
public static class InfrastructureExtensoes
{
    /// <summary>
    /// Registra o DbContext, os repositórios, serviços externos e demais dependências da camada de Infraestrutura.
    /// </summary>
    public static IServiceCollection AdicionarInfrastructure(
        this IServiceCollection services,
        IConfiguration configuration)
    {
        // Registra o DbContext com SQL Server
        services.AddDbContext<AluguelDbContext>(opcoes =>
            opcoes.UseSqlServer(
                configuration.GetConnectionString("AluguelDb"),
                sql =>
                {
                    sql.MigrationsAssembly(typeof(AluguelDbContext).Assembly.FullName);
                    sql.EnableRetryOnFailure(
                        maxRetryCount: 5,
                        maxRetryDelay: TimeSpan.FromSeconds(10),
                        errorNumbersToAdd: null);
                }));

        // Registra os repositorios — seguindo DIP (SOLID)
        services.AddScoped<IApartamentoRepositorio, ApartamentoRepositorio>();
        services.AddScoped<IInquilinoRepositorio, InquilinoRepositorio>();
        services.AddScoped<IFaturaRepositorio, FaturaRepositorio>();
        services.AddScoped<IDependenteRepositorio, DependenteRepositorio>();
        services.AddScoped<IConfiguracaoRepositorio, ConfiguracaoRepositorio>();
        services.AddScoped<IGastoManutencaoRepositorio, GastoManutencaoRepositorio>();
        services.AddScoped<IContratoInquilinoRepositorio, ContratoInquilinoRepositorio>();
        services.AddScoped<IHostRepositorio, HostRepositorio>();

        // Registra o cliente HTTP nomeado para a API do Asaas
        // A URL base e a ApiKey sao lidas do appsettings.json (secao "Asaas")
        services.AddHttpClient("Asaas", (sp, client) =>
        {
            var asaasBaseUrl = configuration["Asaas:BaseUrl"]
                ?? "https://sandbox.asaas.com/api/v3";
            var asaasApiKey = configuration["Asaas:ApiKey"] ?? string.Empty;

            client.BaseAddress = new Uri(asaasBaseUrl);
            // Header de autenticacao exigido pela API do Asaas
            client.DefaultRequestHeaders.Add("access_token", asaasApiKey);
            client.DefaultRequestHeaders.Add("Accept", "application/json");
        });

        // Registra o servico de gateway de pagamento (implementacao Asaas)
        services.AddScoped<IServicoGatewayPagamento, AsaasServicoGatewayPagamento>();

        // Registra o servico de armazenamento de arquivos (contratos)
        services.AddScoped<IArquivoStorageServico, ArquivoStorageServico>();

        // Registra o servico de geracao de tokens JWT
        services.AddScoped<IJwtServico, JwtServico>();

        // Registra o servico de hashing de senhas (PBKDF2-SHA256)
        services.AddScoped<ISenhaServico, SenhaServico>();

        // Registra o servico de envio de e-mails (SMTP)
        services.AddScoped<IEmailServico, EmailServico>();

        // Registra o gerador de payload PIX (EMV/copia-e-cola, sem API externa)
        services.AddScoped<IPixPayloadGerador, PixPayloadGerador>();

        // Registra o contexto de tenant (multi-tenancy via JWT hostId claim)
        services.AddHttpContextAccessor();
        services.AddScoped<ITenantContexto, TenantContexto>();

        return services;
    }
}

using BackEndAluguel.Domain.Entidades;
using BackEndAluguel.Domain.Enumeradores;
using BackEndAluguel.Domain.Interfaces;
using BackEndAluguel.Infrastructure.Contexto;
using Microsoft.EntityFrameworkCore;

namespace BackEndAluguel.Infrastructure.Repositorios;

/// <summary>
/// Implementação concreta do repositório de <see cref="Fatura"/>.
/// Herda as operações genéricas do <see cref="RepositorioBase{T}"/> e adiciona
/// queries específicas para faturas mensais.
/// </summary>
public class FaturaRepositorio : RepositorioBase<Fatura>, IFaturaRepositorio
{
    /// <summary>
    /// Inicializa o repositório com o contexto do banco de dados.
    /// </summary>
    public FaturaRepositorio(AluguelDbContext contexto) : base(contexto)
    {
    }

    /// <summary>
    /// Verifica se já existe uma fatura para o inquilino no mês de referência informado.
    /// </summary>
    public async Task<bool> ExisteParaMesReferenciaAsync(
        Guid inquilinoId, string mesReferencia, CancellationToken cancellationToken = default)
        => await DbSet.AnyAsync(
            f => f.InquilinoId == inquilinoId && f.MesReferencia == mesReferencia.Trim(),
            cancellationToken);

    /// <summary>
    /// Retorna todas as faturas de um inquilino específico, ordenadas por mês.
    /// </summary>
    public async Task<IEnumerable<Fatura>> ObterPorInquilinoAsync(
        Guid inquilinoId, CancellationToken cancellationToken = default)
        => await DbSet.AsNoTracking()
            .Where(f => f.InquilinoId == inquilinoId)
            .OrderByDescending(f => f.DataLimitePagamento)
            .ToListAsync(cancellationToken);

    /// <summary>
    /// Retorna todas as faturas com o status informado.
    /// </summary>
    public async Task<IEnumerable<Fatura>> ObterPorStatusAsync(
        StatusFatura status, CancellationToken cancellationToken = default)
        => await DbSet.AsNoTracking()
            .Where(f => f.Status == status)
            .OrderBy(f => f.DataLimitePagamento)
            .ToListAsync(cancellationToken);

    /// <summary>
    /// Retorna todas as faturas vencidas: data limite ultrapassada e status diferente de Pago.
    /// Utilizado para o processamento automático de marcação de atraso.
    /// </summary>
    public async Task<IEnumerable<Fatura>> ObterFaturasVencidasAsync(CancellationToken cancellationToken = default)
    {
        var hoje = DateOnly.FromDateTime(DateTime.Today);
        return await DbSet
            .Where(f => f.Status != StatusFatura.Pago && f.DataLimitePagamento < hoje)
            .ToListAsync(cancellationToken);
    }

    /// <summary>
    /// Busca a fatura de um inquilino para um mês de referência específico.
    /// </summary>
    public async Task<Fatura?> ObterPorInquilinoEMesAsync(
        Guid inquilinoId, string mesReferencia, CancellationToken cancellationToken = default)
        => await DbSet.FirstOrDefaultAsync(
            f => f.InquilinoId == inquilinoId && f.MesReferencia == mesReferencia.Trim(),
            cancellationToken);

    public async Task<IEnumerable<Fatura>> ObterPorMesReferenciaComDetalhesAsync(
        string mesReferencia, CancellationToken cancellationToken = default)
        => await DbSet.AsNoTracking()
            .Include(f => f.Inquilino)
                .ThenInclude(i => i!.Apartamento)
            .Where(f => f.MesReferencia == mesReferencia.Trim())
            .ToListAsync(cancellationToken);

    public async Task<IEnumerable<Fatura>> ObterPagasPorAnoAsync(int ano, CancellationToken cancellationToken = default)
        => await DbSet.AsNoTracking()
            .Include(f => f.Inquilino)
                .ThenInclude(i => i!.Apartamento)
            .Where(f => f.Status == StatusFatura.Pago && f.MesReferencia.EndsWith($"/{ano}"))
            .OrderBy(f => f.MesReferencia)
            .ToListAsync(cancellationToken);

    /// <summary>
    /// Busca uma fatura pelo ID externo de cobranca no Asaas.
    /// Utilizado pelo webhook de confirmacao de pagamento PIX.
    /// </summary>
    public async Task<Fatura?> ObterPorCobrancaAsaasIdAsync(string cobrancaAsaasId, CancellationToken cancellationToken = default)
        => await DbSet.FirstOrDefaultAsync(
            f => f.CobrancaAsaasId == cobrancaAsaasId,
            cancellationToken);
}

