using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Text;
using BackEndAluguel.Application.Auth;
using Microsoft.Extensions.Configuration;
using Microsoft.IdentityModel.Tokens;

namespace BackEndAluguel.Infrastructure.Servicos;

/// <summary>
/// Implementacao concreta do servico de geracao de tokens JWT.
/// Utiliza a chave secreta, issuer e audience definidos no appsettings.json.
/// </summary>
public class JwtServico : IJwtServico
{
    private readonly IConfiguration _configuracao;

    /// <summary>Inicializa o servico JWT com as configuracoes da aplicacao.</summary>
    public JwtServico(IConfiguration configuracao)
    {
        _configuracao = configuracao;
    }

    /// <summary>
    /// Gera um token JWT para o administrador (host/locador) autenticado pelo banco de dados.
    /// </summary>
    public (string Token, DateTime Expiracao) GerarTokenHost(Guid hostId, string nomeCompleto, string email)
    {
        var claims = new List<Claim>
        {
            new(ClaimTypes.NameIdentifier, hostId.ToString()),
            new(ClaimTypes.Name, nomeCompleto),
            new(ClaimTypes.Email, email),
            new(ClaimTypes.Role, "Host"),
            new("hostId", hostId.ToString()),
            new(JwtRegisteredClaimNames.Sub, hostId.ToString()),
            new(JwtRegisteredClaimNames.Jti, Guid.NewGuid().ToString())
        };

        return GerarToken(claims);
    }

    /// <summary>
    /// Gera um token JWT para um inquilino autenticado.
    /// Retorna o token assinado e a data de expiracao UTC.
    /// </summary>
    public (string Token, DateTime Expiracao) GerarTokenInquilino(Guid inquilinoId, string nomeCompleto, string cpf)
    {
        var claims = new List<Claim>
        {
            new(ClaimTypes.NameIdentifier, inquilinoId.ToString()),
            new(ClaimTypes.Name, nomeCompleto),
            new(ClaimTypes.Role, "Inquilino"),
            new("cpf", cpf),
            new("inquilinoId", inquilinoId.ToString()),
            new(JwtRegisteredClaimNames.Sub, inquilinoId.ToString()),
            new(JwtRegisteredClaimNames.Jti, Guid.NewGuid().ToString())
        };

        return GerarToken(claims);
    }

    /// <summary>
    /// Metodo auxiliar que assina e serializa o token JWT com as claims fornecidas.
    /// Utiliza HMAC-SHA256 com a chave secreta do appsettings.json.
    /// </summary>
    private (string Token, DateTime Expiracao) GerarToken(IEnumerable<Claim> claims)
    {
        var chaveSecreta = _configuracao["Jwt:SecretKey"]
            ?? throw new InvalidOperationException("Chave secreta JWT nao configurada.");

        var issuer = _configuracao["Jwt:Issuer"] ?? "GestAluguelAPI";
        var audience = _configuracao["Jwt:Audience"] ?? "GestAluguelFrontEnd";
        var horasExpiracao = int.TryParse(_configuracao["Jwt:ExpiracaoHoras"], out var h) ? h : 24;
        var expiracao = DateTime.UtcNow.AddHours(horasExpiracao);

        var chaveSimetrica = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(chaveSecreta));
        var credenciais = new SigningCredentials(chaveSimetrica, SecurityAlgorithms.HmacSha256);

        var token = new JwtSecurityToken(
            issuer: issuer,
            audience: audience,
            claims: claims,
            expires: expiracao,
            signingCredentials: credenciais);

        return (new JwtSecurityTokenHandler().WriteToken(token), expiracao);
    }
}

using System.Text;
using BackEndAluguel.Domain.Interfaces;

namespace BackEndAluguel.Infrastructure.Servicos;

/// <summary>
/// Implementação do gerador de payload PIX no padrão EMV do Banco Central do Brasil.
/// Gera o código "copia-e-cola" sem depender de qualquer API externa.
///
/// Referência: https://www.bcb.gov.br/content/estabilidadefinanceira/pix/Regulamento_Pix/II-ManualdePadroesparaIniciacaodoPix-versao3.pdf
/// </summary>
public class PixPayloadGerador : IPixPayloadGerador
{
    /// <summary>
    /// Gera o payload PIX EMV completo com CRC16-CCITT.
    /// </summary>
    public string Gerar(string chavePix, string nomeRecebedor, string cidadeRecebedor,
                        decimal? valor = null, string? txId = null)
    {
        // Normaliza campos
        nomeRecebedor = Normalizar(nomeRecebedor, 25);
        cidadeRecebedor = Normalizar(cidadeRecebedor, 15);
        txId = string.IsNullOrWhiteSpace(txId) ? "***" : NormalizarTxId(txId, 25);

        // Merchant Account Info (ID 26)
        var merchantAccountInfo = MontarCampo("00", "BR.GOV.BCB.PIX") +
                                  MontarCampo("01", chavePix.Trim());
        var campoMerchant = MontarCampo("26", merchantAccountInfo);

        // Additional Data Field Template (ID 62) → txid (ID 05)
        var additionalData = MontarCampo("05", txId);
        var campo62 = MontarCampo("62", additionalData);

        // Monta payload sem CRC
        var payload = new StringBuilder();
        payload.Append(MontarCampo("00", "01"));       // Payload format indicator
        payload.Append(campoMerchant);                  // Merchant account info
        payload.Append(MontarCampo("52", "0000"));      // Merchant category code
        payload.Append(MontarCampo("53", "986"));       // Transaction currency (BRL)

        if (valor.HasValue && valor.Value > 0)
            payload.Append(MontarCampo("54", valor.Value.ToString("F2", System.Globalization.CultureInfo.InvariantCulture)));

        payload.Append(MontarCampo("58", "BR"));        // Country code
        payload.Append(MontarCampo("59", nomeRecebedor));
        payload.Append(MontarCampo("60", cidadeRecebedor));
        payload.Append(campo62);                         // Additional data
        payload.Append("6304");                          // CRC placeholder (sem valor ainda)

        // Calcula e adiciona CRC16
        var crc = CalcularCrc16(payload.ToString());
        payload.Append(crc.ToString("X4"));

        return payload.ToString();
    }

    // ─── Helpers ────────────────────────────────────────────────────────────────

    private static string MontarCampo(string id, string valor)
    {
        var len = Encoding.UTF8.GetByteCount(valor);
        return $"{id}{len:D2}{valor}";
    }

    private static string Normalizar(string texto, int maxLen)
    {
        // Remove acentos e caracteres especiais (PIX aceita apenas ASCII imprimível)
        var normalized = texto.Normalize(NormalizationForm.FormD);
        var sb = new StringBuilder();
        foreach (var c in normalized)
        {
            if (System.Globalization.CharUnicodeInfo.GetUnicodeCategory(c)
                != System.Globalization.UnicodeCategory.NonSpacingMark)
                sb.Append(c);
        }
        var result = sb.ToString().Normalize(NormalizationForm.FormC);
        // Mantém apenas ASCII imprimível
        result = new string(result.Where(c => c >= 0x20 && c <= 0x7E).ToArray());
        return result.Length > maxLen ? result[..maxLen] : result;
    }

    private static string NormalizarTxId(string txId, int maxLen)
    {
        var clean = new string(txId.Where(char.IsLetterOrDigit).ToArray());
        return clean.Length > maxLen ? clean[..maxLen] : clean;
    }

    /// <summary>
    /// CRC-16/CCITT-FALSE: poly=0x1021, init=0xFFFF, refin=false, refout=false, xorout=0x0000.
    /// </summary>
    private static ushort CalcularCrc16(string payload)
    {
        var bytes = Encoding.UTF8.GetBytes(payload);
        ushort crc = 0xFFFF;
        foreach (var b in bytes)
        {
            crc ^= (ushort)(b << 8);
            for (var i = 0; i < 8; i++)
            {
                if ((crc & 0x8000) != 0)
                    crc = (ushort)((crc << 1) ^ 0x1021);
                else
                    crc <<= 1;
            }
        }
        return crc;
    }
}

using System.Security.Cryptography;
using BackEndAluguel.Application.Auth;

namespace BackEndAluguel.Infrastructure.Servicos;

/// <summary>
/// Implementação de hashing e verificação de senhas usando PBKDF2-SHA256.
/// Armazena o salt embutido no hash em Base64 — sem dependências externas.
/// Formato: Base64(salt[16] + hash[32]) = 48 bytes = 64 caracteres Base64.
/// </summary>
public class SenhaServico : ISenhaServico
{
    private const int TamanhoSalt = 16;
    private const int TamanhoHash = 32;
    private const int Iteracoes = 100_000;

    /// <summary>
    /// Gera um hash PBKDF2-SHA256 da senha em texto plano com salt aleatório.
    /// </summary>
    public string HashearSenha(string senhaPlana)
    {
        var salt = RandomNumberGenerator.GetBytes(TamanhoSalt);
        var hash = Rfc2898DeriveBytes.Pbkdf2(senhaPlana, salt, Iteracoes, HashAlgorithmName.SHA256, TamanhoHash);

        var resultado = new byte[TamanhoSalt + TamanhoHash];
        Buffer.BlockCopy(salt, 0, resultado, 0, TamanhoSalt);
        Buffer.BlockCopy(hash, 0, resultado, TamanhoSalt, TamanhoHash);

        return Convert.ToBase64String(resultado);
    }

    /// <summary>
    /// Verifica se a senha em texto plano corresponde ao hash armazenado.
    /// Usa comparação de tempo constante para evitar ataques de timing.
    /// </summary>
    public bool VerificarSenha(string senhaPlana, string hashArmazenado)
    {
        byte[] bytes;
        try { bytes = Convert.FromBase64String(hashArmazenado); }
        catch { return false; }

        if (bytes.Length != TamanhoSalt + TamanhoHash)
            return false;

        var salt = bytes[..TamanhoSalt];
        var hashEsperado = bytes[TamanhoSalt..];
        var hashCalculado = Rfc2898DeriveBytes.Pbkdf2(senhaPlana, salt, Iteracoes, HashAlgorithmName.SHA256, TamanhoHash);

        return CryptographicOperations.FixedTimeEquals(hashEsperado, hashCalculado);
    }
}

using System.Security.Claims;
using BackEndAluguel.Application.Comum;
using Microsoft.AspNetCore.Http;

namespace BackEndAluguel.Infrastructure.Servicos;

/// <summary>
/// Implementação de <see cref="ITenantContexto"/> que extrai o HostId
/// do token JWT da requisição HTTP atual via <see cref="IHttpContextAccessor"/>.
/// Quando não há contexto HTTP (background services) ou o JWT não possui a claim
/// <c>hostId</c> (ex.: token de inquilino), retorna <c>null</c> — sinalizando que
/// o filtro de tenant não deve ser aplicado.
/// </summary>
public class TenantContexto : ITenantContexto
{
    private readonly IHttpContextAccessor _httpContextAccessor;

    public TenantContexto(IHttpContextAccessor httpContextAccessor)
    {
        _httpContextAccessor = httpContextAccessor;
    }

    /// <inheritdoc />
    public Guid? ObterHostId()
    {
        var claim = _httpContextAccessor.HttpContext?
            .User?.FindFirst("hostId")?.Value;

        return claim is not null && Guid.TryParse(claim, out var hostId)
            ? hostId
            : null;
    }
}

using BackEndAluguel.Application.Apartamentos.Comandos;
using BackEndAluguel.Application.Apartamentos.Manipuladores;
using BackEndAluguel.Application.Comum.Excecoes;
using BackEndAluguel.Domain.Entidades;
using BackEndAluguel.Domain.Interfaces;
using FluentAssertions;
using Moq;

namespace BackEndAluguel.Tests.Aplicacao;

/// <summary>
/// Testes unitários para os manipuladores CQRS de Apartamento.
/// Usa Moq para simular o repositório e validar o comportamento dos handlers.
/// </summary>
public class ApartamentoManipuladorTestes
{
    private readonly Mock<IApartamentoRepositorio> _repositorioMock;

    /// <summary>
    /// Inicializa os mocks antes de cada teste.
    /// </summary>
    public ApartamentoManipuladorTestes()
    {
        _repositorioMock = new Mock<IApartamentoRepositorio>();
    }

    // =====================================================
    // Testes de CriarApartamentoManipulador
    // =====================================================

    /// <summary>
    /// Verifica que criar um apartamento com dados únicos retorna o DTO corretamente.
    /// </summary>
    [Fact]
    public async Task CriarApartamento_ApartamentoNaoExistente_DeveCriarERetornarDto()
    {
        // Arrange
        _repositorioMock.Setup(r => r.ExisteAsync("101", "A", It.IsAny<CancellationToken>()))
            .ReturnsAsync(false);
        _repositorioMock.Setup(r => r.AdicionarAsync(It.IsAny<Apartamento>(), It.IsAny<CancellationToken>()))
            .Returns(Task.CompletedTask);
        _repositorioMock.Setup(r => r.SalvarAlteracoesAsync(It.IsAny<CancellationToken>()))
            .ReturnsAsync(1);

        var manipulador = new CriarApartamentoManipulador(_repositorioMock.Object);
        var comando = new CriarApartamentoComando("101", "A");

        // Act
        var resultado = await manipulador.Handle(comando, CancellationToken.None);

        // Assert
        resultado.Should().NotBeNull();
        resultado.Numero.Should().Be("101");
        resultado.Bloco.Should().Be("A");
        resultado.Ocupado.Should().BeFalse();

        _repositorioMock.Verify(r => r.AdicionarAsync(It.IsAny<Apartamento>(), It.IsAny<CancellationToken>()), Times.Once);
        _repositorioMock.Verify(r => r.SalvarAlteracoesAsync(It.IsAny<CancellationToken>()), Times.Once);
    }

    /// <summary>
    /// Verifica que criar apartamento duplicado lança RegraDeNegocioExcecao.
    /// </summary>
    [Fact]
    public async Task CriarApartamento_ApartamentoJaExistente_DeveLancarRegraDeNegocioExcecao()
    {
        // Arrange
        _repositorioMock.Setup(r => r.ExisteAsync("101", "A", It.IsAny<CancellationToken>()))
            .ReturnsAsync(true);

        var manipulador = new CriarApartamentoManipulador(_repositorioMock.Object);
        var comando = new CriarApartamentoComando("101", "A");

        // Act
        var acao = async () => await manipulador.Handle(comando, CancellationToken.None);

        // Assert
        await acao.Should().ThrowAsync<RegraDeNegocioExcecao>()
            .WithMessage("*101*");

        _repositorioMock.Verify(r => r.AdicionarAsync(It.IsAny<Apartamento>(), It.IsAny<CancellationToken>()), Times.Never);
    }

    // =====================================================
    // Testes de AtualizarApartamentoManipulador
    // =====================================================

    /// <summary>
    /// Verifica que atualizar apartamento existente retorna DTO atualizado.
    /// </summary>
    [Fact]
    public async Task AtualizarApartamento_ApartamentoExistente_DeveAtualizarERetornarDto()
    {
        // Arrange
        var apartamentoExistente = new Apartamento("101", "A");
        _repositorioMock.Setup(r => r.ObterPorIdAsync(apartamentoExistente.Id, It.IsAny<CancellationToken>()))
            .ReturnsAsync(apartamentoExistente);
        _repositorioMock.Setup(r => r.SalvarAlteracoesAsync(It.IsAny<CancellationToken>()))
            .ReturnsAsync(1);

        var manipulador = new AtualizarApartamentoManipulador(_repositorioMock.Object);
        var comando = new AtualizarApartamentoComando(apartamentoExistente.Id, "202", "B");

        // Act
        var resultado = await manipulador.Handle(comando, CancellationToken.None);

        // Assert
        resultado.Numero.Should().Be("202");
        resultado.Bloco.Should().Be("B");
    }

    /// <summary>
    /// Verifica que atualizar apartamento não encontrado lança EntidadeNaoEncontradaExcecao.
    /// </summary>
    [Fact]
    public async Task AtualizarApartamento_ApartamentoNaoEncontrado_DeveLancarEntidadeNaoEncontradaExcecao()
    {
        // Arrange
        _repositorioMock.Setup(r => r.ObterPorIdAsync(It.IsAny<Guid>(), It.IsAny<CancellationToken>()))
            .ReturnsAsync((Apartamento?)null);

        var manipulador = new AtualizarApartamentoManipulador(_repositorioMock.Object);
        var comando = new AtualizarApartamentoComando(Guid.NewGuid(), "202", "B");

        // Act
        var acao = async () => await manipulador.Handle(comando, CancellationToken.None);

        // Assert
        await acao.Should().ThrowAsync<EntidadeNaoEncontradaExcecao>();
    }

    // =====================================================
    // Testes de RemoverApartamentoManipulador
    // =====================================================

    /// <summary>
    /// Verifica que remover apartamento desocupado funciona corretamente.
    /// </summary>
    [Fact]
    public async Task RemoverApartamento_ApartamentoDesocupado_DeveRemoverERetornarVerdadeiro()
    {
        // Arrange
        var apartamento = new Apartamento("101", "A");
        _repositorioMock.Setup(r => r.ObterPorIdAsync(apartamento.Id, It.IsAny<CancellationToken>()))
            .ReturnsAsync(apartamento);
        _repositorioMock.Setup(r => r.SalvarAlteracoesAsync(It.IsAny<CancellationToken>()))
            .ReturnsAsync(1);

        var manipulador = new RemoverApartamentoManipulador(_repositorioMock.Object);
        var comando = new RemoverApartamentoComando(apartamento.Id);

        // Act
        var resultado = await manipulador.Handle(comando, CancellationToken.None);

        // Assert
        resultado.Should().BeTrue();
        _repositorioMock.Verify(r => r.Remover(apartamento), Times.Once);
    }

    /// <summary>
    /// Verifica que tentativa de remover apartamento ocupado lança RegraDeNegocioExcecao.
    /// </summary>
    [Fact]
    public async Task RemoverApartamento_ApartamentoOcupado_DeveLancarRegraDeNegocioExcecao()
    {
        // Arrange
        var apartamento = new Apartamento("101", "A");
        apartamento.MarcarComoOcupado();

        _repositorioMock.Setup(r => r.ObterPorIdAsync(apartamento.Id, It.IsAny<CancellationToken>()))
            .ReturnsAsync(apartamento);

        var manipulador = new RemoverApartamentoManipulador(_repositorioMock.Object);
        var comando = new RemoverApartamentoComando(apartamento.Id);

        // Act
        var acao = async () => await manipulador.Handle(comando, CancellationToken.None);

        // Assert
        await acao.Should().ThrowAsync<RegraDeNegocioExcecao>()
            .WithMessage("*ocupado*");

        _repositorioMock.Verify(r => r.Remover(It.IsAny<Apartamento>()), Times.Never);
    }
}

