CREATE TABLE [ContratosInquilino] ( [Id] uniqueidentifier NOT NULL, [InquilinoId] uniqueidentifier NOT NULL, [NomeOriginalArquivo] nvarchar(260) NOT NULL, [CaminhoArquivo] nvarchar(500) NOT NULL, [TipoConteudo] nvarchar(100) NOT NULL, [TamanhoBytes] bigint NOT NULL, [Descricao] nvarchar(500) NULL, [CriadoEm] datetime2 NOT NULL, [AtualizadoEm] datetime2 NULL, CONSTRAINT [PK_ContratosInquilino] PRIMARY KEY ([Id]), CONSTRAINT [FK_ContratosInquilino_Inquilinos_InquilinoId] FOREIGN KEY ([InquilinoId]) REFERENCES [Inquilinos] ([Id]) ON DELETE CASCADE );
CREATE INDEX [IX_ContratosInquilino_InquilinoId] ON [ContratosInquilino] ([InquilinoId]);
CREATE TABLE [Dependentes] ( [Id] uniqueidentifier NOT NULL, [NomeCompleto] nvarchar(200) NOT NULL, [Cpf] nvarchar(11) NOT NULL, [Rg] nvarchar(20) NULL, [OrgaoEmissor] nvarchar(20) NULL, [DataNascimento] date NOT NULL, [Telefone] nvarchar(20) NULL, [EstadoCivil] int NOT NULL, [InquilinoId] uniqueidentifier NOT NULL, [CriadoEm] datetime2 NOT NULL, [AtualizadoEm] datetime2 NULL, CONSTRAINT [PK_Dependentes] PRIMARY KEY ([Id]), CONSTRAINT [FK_Dependentes_Inquilinos_InquilinoId] FOREIGN KEY ([InquilinoId]) REFERENCES [Inquilinos] ([Id]) ON DELETE CASCADE );
CREATE UNIQUE INDEX [IX_Dependentes_Cpf] ON [Dependentes] ([Cpf]); CREATE INDEX [IX_Dependentes_InquilinoId] ON [Dependentes] ([InquilinoId]);
CREATE TABLE [Faturas] ( [Id] uniqueidentifier NOT NULL, [MesReferencia] nvarchar(7) NOT NULL, [ValorAluguel] decimal(18,2) NOT NULL, [ValorAgua] decimal(18,2) NOT NULL DEFAULT 0, [ValorLuz] decimal(18,2) NOT NULL DEFAULT 0, [KwMesAnterior] decimal(18,3) NULL, [KwAtual] decimal(18,3) NULL, [KwhValor] decimal(18,4) NULL, [DataLimitePagamento] date NOT NULL, [DataPagamento] date NULL, [CodigoPix] nvarchar(500) NULL, [CobrancaAsaasId] nvarchar(100) NULL, [Status] int NOT NULL, [InquilinoId] uniqueidentifier NOT NULL, [CriadoEm] datetime2 NOT NULL, [AtualizadoEm] datetime2 NULL, CONSTRAINT [PK_Faturas] PRIMARY KEY ([Id]), CONSTRAINT [FK_Faturas_Inquilinos_InquilinoId] FOREIGN KEY ([InquilinoId]) REFERENCES [Inquilinos] ([Id]) ON DELETE CASCADE );
CREATE UNIQUE INDEX [IX_Faturas_InquilinoId_MesReferencia] ON [Faturas] ([InquilinoId], [MesReferencia]);
