-- ============================================================ -- [3] AdicionarDataNascimentoInquilino -- ============================================================ IF NOT EXISTS (SELECT 1 FROM [__EFMigrationsHistory] WHERE [MigrationId] = N'20260429220437_AdicionarDataNascimentoInquilino') BEGIN PRINT '>> Aplicando: AdicionarDataNascimentoInquilino...';
BEGIN TRANSACTION;
-- Adiciona com default temporário (1900-01-01) para linhas existentes ALTER TABLE [Inquilinos] ADD [DataNascimento] date NOT NULL DEFAULT '1900-01-01';
-- Remove o default permanente (EF não usa DEFAULT em colunas novas após criação) DECLARE @constraint_nascimento sysname; SELECT @constraint_nascimento = dc.name FROM sys.default_constraints dc JOIN sys.columns c ON dc.parent_object_id = c.object_id AND dc.parent_column_id = c.column_id WHERE c.object_id = OBJECT_ID(N'[Inquilinos]') AND c.name = N'DataNascimento';
IF @constraint_nascimento IS NOT NULL EXEC('ALTER TABLE [Inquilinos] DROP CONSTRAINT [' + @constraint_nascimento + ']');
INSERT INTO [__EFMigrationsHistory] VALUES (N'20260429220437_AdicionarDataNascimentoInquilino', N'9.0.4');
COMMIT; PRINT ' OK.'; END ELSE PRINT ' Ignorado (ja aplicado).';
