-- Novos campos em Inquilinos ALTER TABLE [Inquilinos] ADD [EstadoCivil] int NOT NULL DEFAULT 0, [OrgaoEmissor] nvarchar(20) NOT NULL DEFAULT N'', [Rg] nvarchar(20) NOT NULL DEFAULT N'', [Telefone] nvarchar(20) NOT NULL DEFAULT N'';
-- Nova tabela Hosts CREATE TABLE [Hosts] ( [Id] uniqueidentifier NOT NULL, [NomeCompleto] nvarchar(200) NOT NULL, [Cpf] nchar(11) NOT NULL, [DataNascimento] date NOT NULL, [Email] nvarchar(200) NOT NULL, [SenhaHash] nvarchar(500) NOT NULL, [EmailConfirmado] bit NOT NULL DEFAULT 0, [TokenConfirmacao] nvarchar(100) NULL, [TokenExpiracaoConfirmacao] datetime2 NULL, [CriadoEm] datetime2 NOT NULL, [AtualizadoEm] datetime2 NULL, CONSTRAINT [PK_Hosts] PRIMARY KEY ([Id]) );
CREATE UNIQUE INDEX [IX_Hosts_Cpf] ON [Hosts] ([Cpf]); CREATE UNIQUE INDEX [IX_Hosts_Email] ON [Hosts] ([Email]); CREATE UNIQUE INDEX [IX_Hosts_TokenConfirmacao] ON [Hosts] ([TokenConfirmacao]) WHERE [TokenConfirmacao] IS NOT NULL;
INSERT INTO [__EFMigrationsHistory] VALUES (N'20260430000404_AdicionarHostECamposMorador', N'9.0.4');
COMMIT; PRINT ' OK.'; END ELSE PRINT ' Ignorado (ja aplicado).';
